Let $\mathrm{Higgs}_G$ be the derived moduli stack of $G$-Higgs bundles on $C$, 
equipped with the Hitchin fibration
\begin{align*}
    h\colon \mathrm{Higgs}_G \to \mathrm{B}_G. 
\end{align*}

For a perfect complex $\mathcal{E}$, the above weight condition is given by 
(see Lemma~\ref{lem:perfect})
\begin{align*}
    \mathrm{wt}(\nu^* \mathcal{E}) \subset \left[ \frac{1}{2}c_1(\nu^* \mathbb{L}_{\mathrm{Higgs}_G}^{<0}), \frac{1}{2}c_1(\nu^* \mathbb{L}_{\mathrm{Higgs}_G}^{>0}) \right] +c_1(\nu^* \delta_{w}).
\end{align*}

It is well-known that any small deformation of a type $A$ singularity is again of type $A$ (\cite[Theorem~1.2.48, Corollary~1.2.49]{GreuelLossenShustin}), and therefore there is a derived open subscheme 
\begin{align}\label{intro:BA}
\mathrm{B}_{\operatorname{GL}_r}^A \subset \mathrm{B}_{\operatorname{GL}_r}
\end{align}
corresponding to spectral curves
with at worst type $A$ singularities.

\emph{(Theorem~\ref{thm:GL}, Theorem~\ref{thm:SL}, Theorem~\ref{thm:PGL})}\label{intro:mainthm}
    For $G=\operatorname{GL}_r$, $\operatorname{SL}_r$ or $\operatorname{PGL}_r$, the Dolbeault geometric Langlands conjecture holds over the open subset 
    \begin{align*}
        \mathrm{B}_G^{\circ}=\mathrm{B}_{G}^{\mathrm{ell}} \cup \mathrm{B}_G^A \subset \mathrm{B}_G.
    \end{align*}

Here, for an open subset $\mathrm{B}_G^{\circ} \subset \mathrm{B}_G$, we say that the
\textit{Dolbeault geometric Langlands conjecture holds over $\mathrm{B}_G^{\circ}$}
if there is a $\mathrm{B}_G^{\circ}$-linear equivalence 
\begin{align}\label{intro:IndL2}
        \operatorname{IndCoh}_{\mathcal{N}}(\mathrm{Higgs}_{{}^{L}G}(w)^{\mathrm{ss}}\times_{\mathrm{B}_G}\mathrm{B}_G^{\circ})_{-\chi}
        \stackrel{\sim}{\to}
        \operatorname{IndL}_{\mathcal{N}}(\mathrm{Higgs}_G(\chi)\times_{\mathrm{B}_G}\mathrm{B}_G^{\circ})_w.
\end{align}

\emph{(Theorem~\ref{thm:whit})}\label{thm:Whit:intro}
The Whittaker normalization Conjecture~\ref{intro:conj:whit} is true over
$\mathcal{B}=\mathcal{B}^A$.

In these cases, we also use the functors 
