\begin{align}\label{ineq:deg}
    \frac{\deg F'}{\operatorname{rank} F'} <(\leqslant) \frac{\deg F}{\operatorname{rank} F}. 
\end{align}

\label{exam:Atype}
(1) For $G=\operatorname{GL}_2$, we have $\mathrm{B}_{\operatorname{GL}_2}^A=\mathrm{B}_{\operatorname{GL}_2}^{\mathrm{red}}$. 
Indeed, an equation of the spectral curve for $G=\operatorname{GL}_2$ is 
\begin{align*}
    y^2 -b_1 y +b_2=0
\end{align*}
for $b_i \in H^0(C, \Omega_C^i)$. It is reduced if and only if 
$b_1^2 -4b_2 \neq 0$ in $H^0(C, \Omega_C^2)$.
Therefore, after the change of variables $y\mapsto y-b_1/2$, the 
above equation is formally locally of the form $y^2-x^m=0$ for some $m$. 

(2)  
For each decomposition $r=r_1+\cdots+r_k$, we have the addition map
\begin{align*}
    \mathrm{B}_{\operatorname{GL}_{r_1}} \times \cdots \times \mathrm{B}_{\operatorname{GL}_{r_k}}
    \to \mathrm{B}_{\operatorname{GL}_r}
\end{align*}
given by adding spectral curves as effective divisors. 
Then $\mathrm{B}_{\operatorname{GL}_r}^{A}$ contains the image of the generic point of the above map. 
Indeed, for a general choice of spectral curves 
$\mathcal{C}_1, \ldots, \mathcal{C}_k$, where $\mathcal{C}_i$ corresponds to 
$b_i \in \mathrm{B}_{\operatorname{GL}_{r_i}}$, the curves $\mathcal{C}_i$ are smooth, and 
$\mathcal{C}_i$ and $\mathcal{C}_j$ intersect transversely at points which are not ramification points 
of the projections $\mathcal{C}_i \to C$ and $\mathcal{C}_j \to C$. 
Then the $\operatorname{GL}_r$-spectral curve $\mathcal{C}_1+\cdots+\mathcal{C}_k$ corresponds to a point in 
$\mathrm{B}_{\operatorname{GL}_r}^{A}$. 

