there is an isomorphism 
\begin{align*}
    (\operatorname{id}\times s)^* \mathcal{P} \cong \mathcal{O}_{\mathcal{H}}.
\end{align*}

\emph{(\cite[Conjecture~4.4]{TodaGL2})}\label{conj:Whit}
    For an open subset $\mathcal{B} \subset \mathrm{B}_{\operatorname{GL}_r}^{\mathrm{red, cl}}$, there is an isomorphism 
    \begin{align*}
        \Phi(\mathcal{O}_{\mathcal{H}(w)^{\mathrm{ss}}}) \cong s_{!}\mathcal{O}_{\mathcal{B}}.
    \end{align*}

\emph{(\cite[Theorem~4.29]{TodaGL2})}\label{thm:WhitGL}
For $G=\operatorname{GL}_r$ and an open subset $\mathcal{B} \subset \mathrm{B}_{\operatorname{GL}_r}^{\mathrm{red, cl}}$, 
suppose that the following conditions hold: 
\begin{enumerate}
    \item Conjecture~\ref{conj:Whit} holds;
    \item For $b\in \mathcal{B}$, let $x\in \mathcal{C}_b$ be a singular point and $I_x \subset \widehat{\mathcal{O}}_{\mathcal{C}_b, x}$
    the conductor ideal. Then $\widehat{\mathcal{O}}_{\mathcal{C}_b, x}/I_x$ is isomorphic to $k[t]/t^m$ for some $m\geqslant 1$.
\end{enumerate}
Then the functor (\ref{induce:Phi0}) induces an equivalence
\begin{align}\label{equiv:WhitL}
    \Phi \colon \operatorname{IndCoh}_{\mathcal{N}}(\mathcal{H}(w)^{\mathrm{ss}})_{-\chi'} \stackrel{\sim}{\to} \operatorname{IndL}_{\mathcal{N}}(\mathcal{H}(\chi))_{w'}.
\end{align}

\label{rmk:thm1}
Since we have equivalences (\cite[Remark~2.14]{TodaGL2})
\begin{align*}
 \operatorname{IndCoh}_{\mathcal{N}}(\mathcal{H}(w)^{\mathrm{ss}})_{-\chi'} &\simeq
    \operatorname{IndCoh}_{\mathcal{N}}(\mathcal{H}(w)^{\mathrm{ss}})_{-\chi}, \\
 \operatorname{IndL}_{\mathcal{N}}(\mathcal{H}(\chi))_{w'} &\simeq \operatorname{IndL}_{\mathcal{N}}(\mathcal{H}(\chi))_{w}
\end{align*}
the equivalence (\ref{equiv:WhitL}) implies that DL conjecture holds over $\mathcal{B}$.

\label{rmk:thm2}
The condition (ii) in Theorem~\ref{thm:WhitGL} is automatic 
for $b\in \mathrm{B}_{\operatorname{GL}_r}^{A, \mathrm{cl}}$, see~\cite[Example~4.19]{TodaGL2}.

We consider the base-change which removes the $k[-1]$-factor of $\mathfrak{M}_S(1)$
\begin{align*}
\mathrm{Hecke}_{\operatorname{GL}_r}':=\mathrm{Hecke}_{\mathrm{GL}_r}\times_{\mathfrak{M}(1)}(S\times B\mathbb{G}_m). 
\end{align*}

We consider the following open subset of $\mathrm{B}_{\operatorname{GL}_r}^{\mathrm{cl}}$
\begin{align*}
   \mathcal{B}= \mathcal{B}^{A} :=\mathrm{B}_{\operatorname{GL}_r}^{A, \mathrm{cl}}.
\end{align*}

\emph{(cf.~\cite[Lemma~5.2]{TodaGL2})}\label{lem:Qp}
There is an exact sequence 
\begin{align}\label{exact:LE}
    0\to \mathcal{L} \to E \to \bigoplus_{p\in N}Q_p \to 0
\end{align}
where $\mathcal{L}$ is a line bundle on $\mathcal{C}_b$ and $Q_p$ is a zero-dimensional sheaf of length $n_p$, 
where $1\leqslant n_p \leqslant m_p'$, which is isomorphic to $\mathcal{O}_{W_p}$ for 
a closed subscheme $W_p \hookrightarrow Z_p$. 

In particular, for any $x\in \mathcal{C}_b$ we have 
\begin{align}\label{dim:est}
    \dim \operatorname{Hom}(E, \mathcal{O}_x) \leqslant 2
\end{align}
and $\dim \operatorname{Hom}(E, \mathcal{O}_x)=1$ if $x\in \mathcal{C}_b$ is a smooth point.

\label{prop:resol}
The sheaf $\mathcal{P}_E$ admits a left resolution of the following form for some $k_i \in \mathbb{Z}_{\geqslant 0}$
    \begin{align}\label{resol:VE}
        \cdots \to \mathcal{V}_E^{\oplus k_1} \to \mathcal{V}_E^{\oplus k_0} \to \mathcal{P}_E \to 0.
    \end{align}

\textit{Idea of the proof.}
For simplicity, we explain the simplest case, that is $\mathcal{L}=\mathcal{O}_{\mathcal{C}_b}$, $N=\{p\}$
and $\mathcal{C}_b$ has a nodal singularity at $p$ (i.e.\ $m_p=2$), 
so that we have the exact sequence 
\begin{align}\label{exact:OEOp}
    0\to \mathcal{O}_{\mathcal{C}_b} \to E \to \mathcal{O}_{p} \to 0
\end{align}
In this case, we show the existence of an exact sequence in $\operatorname{Coh}^{\heartsuit}(\mathcal{H}_b)$
\begin{align}\label{exact:Vp}
0\to \mathcal{P}_E \to \mathcal{V}_E \to \mathcal{P}_E \to 0.
\end{align}
Indeed, then we have the left resolution 
\begin{align*}
    \cdots \to \mathcal{V}_E \to \mathcal{V}_E \to \mathcal{P}_E \to 0.
\end{align*}

For a line bundle $F$ on $\mathcal{C}_b$, by the Deligne pairing (\ref{def:Psharp}) and the exact sequence (\ref{exact:OEOp}),
we have the following identification of the fiber of $\mathcal{P}_E$ at $F$: 
    \begin{align}\label{left:res}
        \mathcal{P}_E|_{F}=F|_{p}.
    \end{align}
    By the assumption on the singularity of $\mathcal{C}_b$, 
    we have
    \begin{align*}
        2p:=\pi|_{\mathcal{C}_b}^{-1}(c)_p \cong \operatorname{Spec} k[t]/(t^2).
    \end{align*}
     Indeed, the fiber over $c$ is obtained by setting $x=0$ in the local model (\ref{loc:model}), hence it is $\operatorname{Spec} k[t]/(t^2)$.
    By the definition of $\mathcal{V}_E$, we have 
    \begin{align*}
        \mathcal{V}_E|_{F}=F|_{2p}.
    \end{align*}
Then from the exact sequence 
\begin{align*}
0\to \mathcal{O}_p \to \mathcal{O}_{2p} \to \mathcal{O}_p \to 0
\end{align*}
there is an exact sequence 
\begin{align}\label{exact:F}
    0\to \mathcal{P}_E|_{F} \to \mathcal{V}_E|_{F} \to \mathcal{P}_E|_{F} \to 0.
\end{align}
Namely we have the exact sequence (\ref{exact:Vp}) on $\mathcal{H}_b^{\mathrm{reg}}$. 

On the other hand, for $x\in \mathcal{C}_b$, let $E_x=I_x^{\vee}$ be the dual of the ideal sheaf $I_x \subset \mathcal{O}_{\mathcal{C}_b}$, which fits into 
an exact sequence 
    \begin{align*}
        0\to \mathcal{O}_{\mathcal{C}_b} \to E_x \to \mathcal{O}_x \to 0.
    \end{align*}
    The above construction gives a family of objects of $\operatorname{Coh}^{\heartsuit}(\mathcal{C}_b)$ parametrized by $x\in \mathcal{C}_b$, 
    and hence there is a map $\mathcal{C}_b \to \mathcal{H}_b$ sending $x\in \mathcal{C}_b$ to $E_x$. By restricting it to $2p \hookrightarrow \mathcal{C}_b$, we obtain the map $2p \to \mathcal{H}_b$. By pulling back the Arinkin sheaf $\mathcal{P}$ on 
    $\mathcal{H}\times_{\mathcal{B}} \mathcal{H}$ to $2p \times_{\mathcal{B}}\mathcal{H}$, and pushing-forward to $\mathcal{H}_b$, we obtain the Cohen--Macaulay sheaf 
    \begin{align*}
        \widetilde{\mathcal{P}}_E \in \operatorname{Coh}^{\heartsuit}(\mathcal{H}_b). 
    \end{align*}
    It fits into the exact sequence 
    \begin{align}\label{exact:tilde}
        0\to \mathcal{P}_E \to \widetilde{\mathcal{P}}_E \to \mathcal{P}_E \to 0.
    \end{align}
   From the construction, we have $\widetilde{\mathcal{P}}_E|_{\mathcal{H}_b^{\mathrm{reg}}}\cong \mathcal{V}_E|_{\mathcal{H}_b^{\mathrm{reg}}}$
   and the above exact sequence is identified with (\ref{exact:F}) over $\mathcal{H}_b^{\mathrm{reg}}$. 

   Then if the complement of $\mathcal{H}_b^{\mathrm{reg}} \subset \mathcal{H}_b$ were of codimension at least two, then 
   we have $\widetilde{\mathcal{P}}_E=\mathcal{V}_E$ by the uniqueness of Cohen--Macaulay extension. In particular, we have the exact sequence (\ref{exact:Vp}) by (\ref{exact:tilde}). 
   However, although $\mathcal{H}_b^{\mathrm{reg}} \subset \mathcal{H}_b$ is dense (see~\cite[Remark~2.5]{TodaGL2}), its complement may be of codimension one; instead we take a flat deformation $E_{\Delta}$
of $E$ over a smooth affine $0\in \Delta$ with $\dim \Delta>0$ such that the induced map 
\begin{align*}\Delta \to \mathcal{H} \to \mathcal{B}
\end{align*}
sends the generic point to the locus $\mathcal{B}^{\mathrm{sm}} \subset \mathcal{B}$ corresponding to the smooth 
spectral curves. Then since $\mathcal{H}^{\mathrm{reg}}\times_{\mathcal{B}}\mathcal{B}^{\mathrm{sm}}=\mathcal{H}\times_{\mathcal{B}}\mathcal{B}^{\mathrm{sm}}$, $\mathcal{H}_{\Delta}\to \Delta$ is flat, and $\mathcal{H}_b^{\mathrm{reg}} \subset \mathcal{H}_b$ is dense, 
the complement of $\mathcal{H}_{\Delta}^{\mathrm{reg}} \subset \mathcal{H}_{\Delta}$ is of codimension 
at least two. Here $(-)_{\Delta}$ is the base change $(-)\times_{\mathcal{B}}\Delta$. 
We then apply the above construction for 
$E_{\Delta}$, restrict it to $0\in \Delta$, and conclude that $\widetilde{\mathcal{P}}_E=\mathcal{V}_E$.

We take the line bundle $\mathcal{L}$ and $Q_p$ for $p\in N$ with length $n_p$ as in Lemma~\ref{lem:Qp}.
We divide the proof into 3 steps. 
\begin{step}
    Reduction to the weight inequality.
\end{step}
Let $\nu$ be a map 
\begin{align*}
    \nu \colon B\mathbb{G}_m \to \mathcal{H}
\end{align*}
corresponding to the object 
\begin{align*}
M=M_1 \oplus \cdots \oplus M_k, \ M_i \in \operatorname{Coh}^{\heartsuit}(\mathcal{C}_b)
\end{align*}
such that $r_i:=\operatorname{rank}(\pi_{*}M_i)$
satisfy $r_1+\cdots+r_k=r$, and 
with $\mathbb{G}_m$-weight
\begin{align*}(\nu_1, \ldots, \nu_k), \ 
\nu_1>\cdots>\nu_k.
\end{align*}
Let $\delta_{w'}$ be the $\mathbb{Q}$-line bundle on $\mathcal{H}$ defined as in (\ref{deltaw})
\begin{align*}
    \delta_{w'}=\det (\mathcal{F}|_{c\times \mathcal{H}})^{w'/r}.
\end{align*}
Since $\mathcal{V}_E$ is perfect on $\mathcal{H}$ (as it is a push-forward of a vector bundle under the regular closed immersion $i_b \colon \mathcal{H}_b \hookrightarrow \mathcal{H}$),
it is enough to show the following by Lemma~\ref{lem:perfect} and Lemma~\ref{lem:eta}
\begin{align}\label{wt:V1}
    \mathrm{wt}(\nu^* \mathcal{V}_E) \subset \left[\frac{1}{2}c_1(\nu^* \mathbb{L}_{\mathcal{H}}^{<0}), 
    \frac{1}{2}c_1(\nu^* \mathbb{L}_{\mathcal{H}}^{>0})\right]+c_1(\nu^* \delta_{w'}).
\end{align}

Note that we have 
\begin{align*}
    \mathcal{C}_b=C_1 \cup \cdots \cup C_k, \ C_i:=\mathrm{Supp}(M_i)
\end{align*}
where $C_i$ is a reduced curve, which is not necessarily irreducible. 
We set 
\begin{align*}
    l_i:=\deg_{C_i}(\mathcal{L}|_{C_i})=\chi(\mathcal{L}|_{C_i})-\chi(\mathcal{O}_{C_i}).
\end{align*}
Since we have (using Lemma~\ref{lem:add})
\begin{align*}
    w'=\deg_{\mathcal{C}_b}(\mathcal{L})+\sum_{p\in N}\mathrm{length}(Q_p)
    =\sum_{i=1}^k l_i+\sum_{p\in N}n_p
\end{align*}
we have the equality 
\begin{align*}
    c_1(\nu^* \delta_{w'})=\frac{1}{r}\left(\sum_{i=1}^k l_i+\sum_{p\in N}n_p  \right)
  \sum_{i=1}^k r_i \nu_i.
\end{align*}
We also have the equality by Lemma~\ref{lem:Gmwt:L}
\begin{align*}
    c_1(\nu^* \mathbb{L}_{\mathcal{H}}^{<0})=\sum_{i>j} (2g-2)r_i r_j(\nu_i-\nu_j).
\end{align*}

A $\nu$-weight of $\mathcal{V}_E$ is of the form 
\begin{align}\label{wt:VE}
    \sum_{i=1}^k l_i \nu_i+\sum_{p\in N}(a_p\nu_{\alpha(p)}+b_p\nu_{\beta(p)})
\end{align}
where $1\leqslant \alpha(p) \leqslant \beta(p) \leqslant k$ satisfies $p \in C_{\alpha(p)}\cap C_{\beta(p)}$, 
and $a_p, b_p$ satisfy 
\begin{align*}
    a_p+b_p=n_p, \ a_p, b_p \geqslant 0.
\end{align*}
Note that the pair $(\alpha(p), \beta(p))$ exists uniquely because $p\in \mathcal{C}_b$ is of type $A$ (i.e.\ there are at most two local branches). Here the first term of (\ref{wt:VE}) is the $\nu$-weight of $\mathcal{P}_{\mathcal{L}}$ by Lemma~\ref{lem:PLGm}.
The second term at each $p\in N$ is a weight of $\mathcal{V}_p^{\otimes n_p}$ since the set of $\nu$-weights of $\mathcal{V}_p$ is $\{\nu_{\alpha(p)}, \nu_{\beta(p)}\}$. 
We also note that, when $\mathcal V_E$ is regarded as an object of $\operatorname{Coh}(\mathcal{H})$, it means 
$(i_b)_*\mathcal V_E$ for $i_b\colon \mathcal{H}_b\hookrightarrow \mathcal{H}$. Since $i_b$ is obtained by base change from the regular closed immersion 
$\{b\}\hookrightarrow \mathcal{B}$, the object $i_b^* (i_b)_{*}\mathcal{V}_E$ is generated by $\mathcal{V}_E$ and other Koszul factors, which are direct sums of $\mathcal{V}_E$ up to shift. Hence they do not affect the above weight estimate of $\nu^* \mathcal{V}_E$.

Then the lower bound in (\ref{wt:V1}) is equivalent to 
\begin{align} \label{ubound1}
    &\sum_{i>j}(g-1)r_i r_j (\nu_i-\nu_j)  \\
  \notag &\leqslant \sum_{i=1}^k l_i \nu_i+\sum_{p\in N}(a_p\nu_{\alpha(p)}+b_p\nu_{\beta(p)})-\frac{1}{r}\left(\sum_{i=1}^k l_i+\sum_{p\in N}n_p  \right)
  \sum_{i=1}^k r_i \nu_i.
\end{align}
\begin{step}
    The inequalities from the semistability of $E$.
\end{step}
Now suppose that $E$ is semistable. We will derive the inequality (\ref{ubound1})
from the semistability of $E$. 

For a subset $I \subset \{1, \ldots, k\}$, 
we write 
\begin{align*}
    C_I:=\bigcup_{i\in I} C_i, \ r_I:=\sum_{i\in I} r_i, \ 
    l_I:=\sum_{i\in I} l_i=\deg_{C_I}(\mathcal{L}|_{C_I}).
\end{align*}
Here the last identity follows from Lemma~\ref{lem:add}.
We also write $I^{\circ}$ for the complement of $I$ in $\{1, \ldots, k\}$. 
By Lemma~\ref{lem:torsion} below, 
we have the exact sequence 
\begin{align*}
    0\to \mathcal{L}|_{C_I} \to E|_{C_I}\to \bigoplus_{p\in N \cap C_I}Q_p \to 0
\end{align*}
such that the torsion part of $E|_{C_I}$ is 
\begin{align*}
    \bigoplus_{p\in N \cap C_I \cap C_{I^{\circ}}}Q_p \subset E|_{C_I}. 
\end{align*}
Let $E|_{C_I}\twoheadrightarrow E|_{C_I}^{\mathrm{free}}$ be the torsion-free quotient of $E|_{C_I}$. Then we have the 
exact sequence 
\begin{align}\label{ex:E1}
    0\to \mathcal{L}|_{C_I} \to E|_{C_I}^{\mathrm{free}} \to \bigoplus_{p\in (N\cap C_I) \setminus C_{I^{\circ}}}Q_p \to 0. 
\end{align}
The kernel $E'$ of $E\twoheadrightarrow E|_{C_I}^{\mathrm{free}}$
fits into the commutative diagram of exact sequences
\begin{equation}\label{com:exE}
\xymatrix@C=4em{
0 \ar[r]
&
\mathcal{L}|_{C_{I^\circ}}(-C_I)
\ar[r]
\ar@{^{(}->}[d]
&
\mathcal{L}
\ar[r]
\ar@{^{(}->}[d]
&
\mathcal{L}|_{C_I}
\ar[r]
\ar@{^{(}->}[d]
&
0
\\
0 \ar[r]
&
E'
\ar[r]
&
E
\ar[r]
&
E|_{C_I}^{\mathrm{free}}
\ar[r]
&
0
}
\end{equation}
By taking the cokernels, we obtain the exact sequence 
\begin{align}\label{ex:E2}
    0\to \mathcal{L}|_{C_{I^{\circ}}}(-C_I)\to E' \to \bigoplus_{p\in N\cap C_{I^{\circ}}}Q_p  \to 0. 
\end{align}
Here we have used that 
\begin{align*}
  N \setminus ((N\cap C_I)\setminus C_{I^{\circ}})=N\cap C_{I^{\circ}}.  
\end{align*}

By the bottom exact sequence (\ref{com:exE})
and the semistability of $E$, we have the inequality 
\begin{align}\label{ineq:rII}
    \frac{\deg \pi_{*}E'}{r_{I^{\circ}}} \leqslant \frac{\deg \pi_{*}E|_{C_I}^{\mathrm{free}}}{r_I}.
\end{align}
From (\ref{ex:E1}) and the formula (\ref{formula:deg}), we have 
\begin{align*}
\deg \pi_{*}E|_{C_I}^{\mathrm{free}}=l_I-(r_I^2-r_I)(g-1)+\sum_{p\in (N\cap C_I)\setminus C_{I^{\circ}}}n_p
\end{align*}
and from (\ref{ex:E2}) we have 
\begin{align*}
    \deg \pi_{*}E'=l_{I^{\circ}}-(r_{I^{\circ}}^2-r_{I^{\circ}})(g-1)-C_I \cdot C_{I^{\circ}}+\sum_{p\in N \cap C_{I^{\circ}}}n_p.
\end{align*}
By noting that 
$C_I \cdot C_{I^{\circ}}=(2g-2)r_I r_{I^{\circ}}$, 
the inequality (\ref{ineq:rII}) is simplified as 
\begin{align}\label{ineq:lI}
    \frac{1}{r_{I^{\circ}}}\left(\sum_{p\in N \cap C_{I^{\circ}}}n_p  \right)
    -\frac{1}{r_I}\left(\sum_{p\in (N\cap C_I)\setminus C_{I^{\circ}}}n_p  \right) 
    \leqslant \frac{l_I}{r_I}-\frac{l_{I^{\circ}}}{r_{I^{\circ}}}+(g-1)r.
\end{align}

Let $\widetilde{l}_i$ be defined by 
\begin{align*}
    \widetilde{l}_i:=l_i -\frac{r_i}{r}\sum_{j=1}^k l_j.
\end{align*}
Then we have $\widetilde{l}_1+\cdots +\widetilde{l}_k=0$, and 
the inequalities (\ref{ubound1}), (\ref{ineq:lI}) are unchanged after replacing $l_i$ with $\widetilde{l}_i$. 
Therefore we may assume that 
\begin{align}\label{sum:l:VE}l_1+\cdots+l_k=0.
\end{align}
Then by substituting $l_{I}+l_{I^{\circ}}=0$ to (\ref{ineq:lI}), and multiplying $r_I r_{I^{\circ}}/r$,
we obtain 
\begin{align}\label{lI:bound}
    \frac{r_I}{r}\left(\sum_{p\in N \cap C_{I^{\circ}}}n_p  \right)-\frac{r_{I^{\circ}}}{r}
\left(\sum_{p\in (N\cap C_I)\setminus C_{I^{\circ}}}n_p  \right) -(g-1)r_I r_{I^{\circ}}\leqslant l_I.
\end{align}
By setting $\mu_i:=\nu_i-\nu_{i+1}>0$, by (\ref{sum:l:VE}) the right-hand side in (\ref{ubound1}) is 
\begin{align*}
\sum_{i=1}^{k-1}(l_1+\cdots+l_i)\mu_i+\sum_{p\in N}(a_p\nu_{\alpha(p)}+b_p\nu_{\beta(p)})-
\frac{1}{r}\sum_{p\in N}n_p 
  \sum_{i=1}^k r_i \nu_i. 
\end{align*}
By setting $I_i=\{1, \ldots, i\}$ and substituting (\ref{lI:bound}), the right-hand side in (\ref{ubound1}) is at least
\begin{align*}
   & -\sum_{i=1}^{k-1} (g-1)r_{I_i}r_{I_i^{\circ}} \mu_i+\sum_{p\in N}(a_p\nu_{\alpha(p)}+b_p\nu_{\beta(p)})-\frac{1}{r}\sum_{p\in N}n_p 
  \sum_{i=1}^k r_i \nu_i \\
&+\sum_{i=1}^{k-1}\left(\frac{r_{I_i}}{r}\left(\sum_{p\in N \cap C_{I_i^{\circ}}}n_p  \right) 
  -
    \frac{r_{I_i^{\circ}}}{r}\left(\sum_{p\in (N \cap C_{I_i})\setminus C_{I_i^{\circ}}}n_p\right)\right)\mu_i.
\end{align*}
Since we have 
\begin{align*}
        \sum_{i<j}(g-1)r_i r_j (\nu_i-\nu_j)= \sum_{i=1}^{k-1} (g-1)r_{I_i}r_{I_i^{\circ}} \mu_i
\end{align*}
the inequality (\ref{ubound1}) follows if the following inequality holds: 
\begin{align}\label{ineq:lambdap}
   & \sum_{p\in N}(a_p\nu_{\alpha(p)}+b_p\nu_{\beta(p)})-\frac{1}{r}\sum_{p\in N}n_p  
  \sum_{i=1}^k r_i \nu_i \\
&\notag \geqslant \sum_{i=1}^{k-1}\left(-\frac{r_{I_i}}{r}\left(\sum_{p\in N \cap C_{I_i^{\circ}}}n_p  \right) 
  +
    \frac{r_{I_i^{\circ}}}{r}\left(\sum_{p\in (N \cap C_{I_i})\setminus C_{I_i^{\circ}}}n_p\right)\right)\mu_i.
\end{align}

\begin{step}
    Proof of the inequality (\ref{ineq:lambdap}).
\end{step}
In order to prove (\ref{ineq:lambdap}), it is enough to prove this for each $p\in N$, 
so we may assume that $N=\{p\}$.
Recall that $\alpha(p)\leqslant \beta(p)$, therefore 
$\nu_{\beta(p)} \leqslant \nu_{\alpha(p)}$. Then the left-hand side in (\ref{ineq:lambdap}) is at least
\begin{align}\label{lambda:jp}
   n_p \nu_{\beta(p)}-\frac{n_p}{r}
\sum_{i=1}^k r_i \nu_i=n_p\left(\sum_{i=\beta(p)}^{k-1}\frac{r_{I_i^{\circ}}}{r}\mu_i -\sum_{i=1}^{\beta(p)-1}\frac{r_{I_i}}{r}\mu_i\right).
\end{align}
On the other hand, we have 
\begin{align*}
    p \in N \cap C_{I_i^{\circ}} \ \mbox{ if and only if } \ \beta(p) > i
\end{align*}
and 
\begin{align*}
    p\in (N \cap C_{I_i})\setminus C_{I_i^{\circ}}  \ \mbox{ if and only if } \ \beta(p) \leqslant i.
\end{align*}
It follows that (\ref{lambda:jp}) equals the right-hand side in (\ref{ineq:lambdap}), therefore we have the inequality (\ref{ineq:lambdap}). We conclude the lower bound in (\ref{wt:V1}). The upper bound is proved similarly.

\begin{align*}
    C_I:=\bigcup_{i\in I} C_i, \ r_I:=\sum_{i\in I} r_i, \ 
    l_I:=\sum_{i\in I} l_i=\deg_{C_I}(\mathcal{L}|_{C_I}).
\end{align*}

\begin{align}\label{lI:bound}
    \frac{r_I}{r}\left(\sum_{p\in N \cap C_{I^{\circ}}}n_p  \right)-\frac{r_{I^{\circ}}}{r}
\left(\sum_{p\in (N\cap C_I)\setminus C_{I^{\circ}}}n_p  \right) -(g-1)r_I r_{I^{\circ}}\leqslant l_I.
\end{align}

\begin{align*}
    p \in N \cap C_{I_i^{\circ}} \ \mbox{ if and only if } \ \beta(p) > i
\end{align*}

\begin{align*}
    p\in (N \cap C_{I_i})\setminus C_{I_i^{\circ}}  \ \mbox{ if and only if } \ \beta(p) \leqslant i.
\end{align*}

\label{lem:lower}
In the proof of Proposition~\ref{prop:VE}, the lower bound in (\ref{wt:V1}) is achieved only if 
the inequality (\ref{ineq:rII}) is an equality for all $I=I_i$ with $1\leqslant i\leqslant k-1$.

\label{lem:torsion}
In the setting of Lemma~\ref{lem:Qp}, let $\mathcal{C}_b=C'\cup C''$ be a decomposition 
where $C', C''$ are unions of irreducible components (which do not have common irreducible components since $\mathcal{C}_b$ is reduced). Then 
the classical $*$-restriction $E|_{C'} \in \operatorname{Coh}^{\heartsuit}(C')$ fits into 
the exact sequence 
\begin{align}\label{exact:L}
    0\to \mathcal{L}|_{C'} \to E|_{C'} \to \bigoplus_{p\in N\cap C'}Q_p \to 0
\end{align}
such that the torsion part of $E|_{C'}$ is $\oplus_{p\in N\cap C'\cap C''}Q_p$.

The exact sequence (\ref{exact:L}) follows from the long exact sequence 
\begin{align*}
    \cdots \to \mathrm{Tor}_1^{\mathcal{O}_{\mathcal{C}_b}}(Q, \mathcal{O}_{C'}) \to 
    \mathcal{L}|_{C'} \to E|_{C'} \to Q|_{C'} \to 0
\end{align*}
and the first map is a zero map as $\mathcal{L}|_{C'}$ is a line bundle and 
$ \mathrm{Tor}_1^{\mathcal{O}_{\mathcal{C}_b}}(Q, \mathcal{O}_{C'})$ is a zero-dimensional sheaf. 

As for the second statement, it is enough to show that (\ref{exact:L}) splits formally locally 
at any $p\in C'\cap C''$. We set 
\begin{align*}R=\widehat{\mathcal{O}}_{\mathcal{C}_b, p}, \ R'=\widehat{\mathcal{O}}_{C', p}, \ 
R''=\widehat{\mathcal{O}}_{C'', p}, \ M=E\otimes_{\mathcal{O}_{\mathcal{C}_b}}R.
\end{align*}
Since $p\in C'\cap C''$ and the singularity is of type $A$, it has two local branches at $p$; hence the normalization of $R$ is $R'\oplus R''$.
By~\cite[Lemma~4.26]{TodaGL2} and the construction of the exact sequence (\ref{exact:LE}) in~\cite[Lemma~5.2]{TodaGL2}, we have 
\begin{align*}
    R \subset M \subset R' \oplus R''.
\end{align*}
Let $\otimes_R^{\mathrm{cl}}$ be the classical tensor product. 
Then $R' \to M\otimes_R^{\mathrm{cl}} R'$ is a split injection, with splitting given by 
\begin{align*}
    M\otimes_R^{\mathrm{cl}} R' \to (R' \oplus R'')\otimes_R^{\mathrm{cl}} R'=R' \oplus (R' \otimes_R^{\mathrm{cl}} R'') \twoheadrightarrow R'.
\end{align*}

\begin{align*}
        M\otimes_R^{\mathrm{cl}} R' \to (R' \oplus R'')\otimes_R^{\mathrm{cl}} R'=R' \oplus (R' \otimes_R^{\mathrm{cl}} R'') \twoheadrightarrow R'.
    \end{align*}

Let $\mathcal{C} \to \mathcal{B}$ be the universal spectral curve, and consider the projection 
\begin{align*}
    \pi \colon \mathcal{C} \to C\times \mathcal{B}.
\end{align*}

\label{lem:heckeclass}
The stack $\mathcal{H}ecke$ is classical, and the evaluation maps 
\begin{align*}
    \mathrm{ev}_i \colon \mathcal{H}ecke \to \mathcal{H}
\end{align*}
for $i=1, 2$ are flat and surjective of relative dimension one.

By Lemma~\ref{lem:qsmooth}, the relative virtual dimension of $\mathrm{ev}_i$ is one. 
On the other hand, let $p\in \mathcal{H}(k)$ be a $k$-valued point, 
and let $E\in \operatorname{Coh}^{\heartsuit}(\mathcal{C}_b)$ be the corresponding 
torsion-free sheaf. Consider the restriction of $\mathrm{ev}_3$
\begin{align*}
 \mathrm{ev}_3' \colon    (\mathrm{ev}_2^{-1}(p))^{\mathrm{cl}} \to \mathcal{C}_b. 
\end{align*}
Then, for each point $x\in \mathcal{C}_b$, we have 
\begin{align*}
    ((\mathrm{ev}_3')^{-1}(x))^{\mathrm{cl}}
    =\mathbb{P}(\operatorname{Hom}(E, \mathcal{O}_x)).
\end{align*}
By Lemma~\ref{lem:Qp}, this is either $\mathbb{P}^1$ or a point; 
the former case occurs precisely when $E$ is not a line bundle at $x$. 
It follows that $(\mathrm{ev}_2^{-1}(p))^{\mathrm{cl}}$ is one-dimensional, 
which equals the relative virtual dimension of $\mathrm{ev}_2$. 
Therefore we have
\begin{align*}
    \dim \mathcal{H}ecke^{\mathrm{cl}}=\dim \mathcal{H}+1=\operatorname{vdim}\mathcal{H}ecke.
\end{align*}
Hence $\mathcal{H}ecke$ is classical, and $\mathrm{ev}_2$ is flat and surjective of relative dimension one. 

As for the statement for $\mathrm{ev}_1$, 
let $\psi$ be the isomorphism given by the shifted derived dual on $S$:
\begin{align*}
    \psi \colon \mathcal{H} \stackrel{\cong}{\to} \mathcal{H}, \quad E \mapsto E^{\vee},
\end{align*}
where $E^{\vee}=\mathbb{D}_S(E)[1]$. 
Then we have the commutative diagram 
\begin{align}\label{dia:heckedual}
    \xymatrix{
    \mathcal{H}ecke \ar[r]^-{\mathrm{ev}_2} \ar[d]^-{\psi}_-{\cong}  
    & \mathcal{H} \ar[d]^-{\psi }_-{\cong} \\
    \mathcal{H}ecke  \ar[r]^-{\mathrm{ev}_1} & \mathcal{H}.
    }
\end{align}
Here the left vertical arrow is given by taking the shifted derived dual over $S$:
\begin{align*}
    (0\to E_1 \to E_2 \to \mathcal{O}_x \to 0) 
    \mapsto 
    (0\to E_2^{\vee} \to E_1^{\vee} \to \mathcal{O}_x \to 0).
\end{align*}
By the above diagram and the fact that $\mathrm{ev}_2$ is flat and surjective of relative dimension one, 
it follows that $\mathrm{ev}_1$ is flat and surjective of relative dimension one.

\label{lem:Delta}
For each $\ell \geqslant 1$, there is a pointed smooth and connected affine variety 
    $(\Delta, 0)$ for $0\in \Delta$ with $\dim \Delta=\ell$ and an extension of the map (\ref{map:tau0})
    \begin{align}\label{map:Delta}
        \tau \colon \Delta \to \mathcal{H}ecke_{\mathcal{D}_p}, \ \tau|_{0}=\tau_0
    \end{align}
    such that the composition 
    \begin{align}\label{map:DeltaB}
\Delta \to \mathcal{H}ecke_{\mathcal{D}_p} \to \mathcal{H}ecke \to \mathcal{B}
    \end{align}
    sends the generic point of $\Delta$ to $\mathcal{B}^{\mathrm{sm}} \subset \mathcal{B}$, the open 
    subset corresponding to smooth spectral curves.

A lift of $\eta$ is a commutative diagram 
\begin{align}\label{dia:eta}
    \xymatrix{
    & (\mathcal{D}_p)_{\Delta} \ar[d] \ar[dr] \\
    \Delta \ar@<-0.3ex>@{^{(}->}[ru]^-{\eta_D} \ar@<-0.3ex>@{^{(}->}[r]^-{\eta} & \mathcal{C}_{\Delta} \ar[r] & \Delta. 
    }
\end{align}

\label{lem:sigma} After shrinking $\Delta$ and replacing the map (\ref{map:Delta}) if necessary, there is an exact sequence 
    \begin{align}\label{ext:sigma}
        0\to E_{\Delta}' \to E_{\Delta}^{\sigma} \to R_{\Delta}^{\sigma} \to 0
    \end{align}
    such that $E_{\Delta}^{\sigma}$ is a $\Delta$-flat family of rank-one torsion-free sheaves on the fibers of 
    $\mathcal{C}_{\Delta}\to \Delta$. Moreover it is isomorphic to (\ref{exact:EQ}) at $0\in \Delta$ under the 
    identifications 
    \begin{align}\label{identify:sigma}R_{\Delta}^{\sigma}|_{0} \cong \mathcal{O}_{p} \cong 
    R_{\Delta}|_{0}.
\end{align}

    We define $\widetilde{\mathcal{H}ecke}$ to be the fiber product
    \begin{align*}
    \xymatrix{
       \widetilde{\mathcal{H}ecke} \ar[r] \ar[d] \ar@{}[dr]|{\square} & \mathcal{H}ecke \ar[d]^-{\mathrm{ev}_1} \\
       \mathcal{H}ecke \ar[r]_-{\mathrm{ev}_1} & \mathcal{H}.
    }
    \end{align*}
Since $\mathcal{H}ecke, \mathcal{H}$ are classical and $\mathrm{ev}_1$ is flat by Lemma~\ref{lem:heckeclass}, the stack $\widetilde{\mathcal{H}ecke}$ is classical. 
    We then define $\widetilde{\mathcal{H}ecke}_{\mathcal{D}_p}$ to be the fiber product 
    \begin{align}\label{hecke:dp}
        \xymatrix{
        \widetilde{\mathcal{H}ecke}_{\mathcal{D}_p}\ar[r] \ar[d] \ar@{}[rd]|\square & \mathcal{D}_p\times_{\mathcal{B}} \mathcal{D}_p \ar[d] \\
        \widetilde{\mathcal{H}ecke} \ar[r]^{(\mathrm{ev}_3, \mathrm{ev}_3)} & \mathcal{C} \times_{\mathcal{B}} \mathcal{C}.
        }
    \end{align}
    It consists of diagrams in $\operatorname{Coh}^{\heartsuit}(\mathcal{C}_b)$ for $b\in \mathcal{B}$
    \begin{align}\label{dia:xy}
    \xymatrix{
    0\ar[r] & E' \ar[r] \ar@{=}[d] & E \ar[r] & \mathcal{O}_x \ar[r] & 0 \\
    0\ar[r] & E' \ar[r] & \widetilde{E} \ar[r] & \mathcal{O}_y \ar[r] & 0
    }
    \end{align}
    where $x, y \in \mathcal{C}_b$, each horizontal row is exact, together with their lifts $x', y' \in \mathcal{D}_p$.
    Since the left vertical arrow in (\ref{hecke:dp}) is \'etale, the stack 
    $\widetilde{\mathcal{H}ecke}_{\mathcal{D}_p}$ is also classical, and the map 
    \begin{align*}
        \widetilde{\mathcal{H}ecke}_{\mathcal{D}_p} \to \mathcal{H}
    \end{align*}
    is flat of relative dimension two. 
    Let
    \begin{align*}
        \mathcal{Z} \subset \widetilde{\mathcal{H}ecke}_{\mathcal{D}_p}
    \end{align*}
    be the classical closed substack consisting of \eqref{dia:xy} such that $y'=\sigma(x')$. It is enough to show that each irreducible component $\mathcal{Z}' \subset \mathcal{Z}$ is dominant over $\mathcal{B}$.

We show that $\mathcal{Z}'$ is dominant over $\mathcal{B}$
following a similar argument of the proof of~\cite[Lemma~5.5]{TodaGL2}.
Consider the composition 
\begin{align}\label{map:ZH}
    \mathcal{Z} \subset \widetilde{\mathcal{H}ecke}_{\mathcal{D}_p} \to \mathcal{H}ecke \to \mathcal{H}. 
\end{align}
Then over the regular locus $\mathcal{H}^{\mathrm{reg}} \subset \mathcal{H}$, the fibers 
of the above map over $b\in \mathcal{B}$ consist of $(x', y') \in \mathcal{D}_p$, which lie over $b$, such that $y'=\sigma(x')$;
this follows since for a line bundle $E'$ on $\mathcal{C}_b$ the diagram (\ref{dia:xy}) 
is uniquely determined by $x, y \in \mathcal{C}_b$ up to isomorphisms, which 
are in turn determined by their lifts $x', y' \in \mathcal{D}_p$. 
Therefore the map (\ref{map:ZH}) over $\mathcal{H}^{\mathrm{reg}}$ is isomorphic to 
$\mathcal{D}_p \times_{\mathcal{B}}\mathcal{H}^{\mathrm{reg}}$. 
Each irreducible component of $\mathcal{D}_p \times_{\mathcal{B}}\mathcal{H}^{\mathrm{reg}}$
is dominant over $\mathcal{B}$, as we have the factorization 
\begin{align*}
    \mathcal{D}_p \times_{\mathcal{B}}\mathcal{H}^{\mathrm{reg}} \to \mathcal{C} \times_{\mathcal{B}}\mathcal{H}^{\mathrm{reg}} \to \mathcal{B},
\end{align*}
the first map is \'etale, and the second map is dominant 
on each irreducible component. 
Therefore if an irreducible component $\mathcal{Z}' \subset \mathcal{Z}$ 
is not dominant over $\mathcal{B}$, then it lies in the complement of $\mathcal{H}^{\mathrm{reg}}$ in $\mathcal{H}$. Since $\mathcal{H}^{\mathrm{reg}} \subset \mathcal{H}$ 
is an isomorphism in codimension one by Lemma~\ref{lem:codimension}, 
this implies that 
\begin{align}\label{codim:Z}
    \dim \mathcal{Z}' \leqslant \dim (\mathcal{H} \setminus \mathcal{H}^{\mathrm{reg}})+2 \leqslant \dim \mathcal{H}.
\end{align}

However, $\mathcal{Z}'$ is an irreducible component of the classical 
stack $\widetilde{\mathcal{Z}}$, defined by the (classical) Cartesian square 
\begin{align*}
\xymatrix{
    \widetilde{\mathcal{Z}} \ar@<-0.3ex>@{^{(}->}[r] \ar[d] & \widetilde{\mathcal{H}ecke}_{\mathcal{D}_p} \ar[d] \\
    D \ar@<-0.3ex>@{^{(}->}[r]^-{\Delta} & D\times_{\mathcal{B}} D
    }
\end{align*}
The right vertical arrow is the top arrow in (\ref{hecke:dp}), which 
records the points $(x', y')$ of a lift of $(x, y)$ in the diagram (\ref{dia:xy}), composed with the double covering map $\mathcal{D}_p \to D$ in the diagram (\ref{etale:D}). 
We have decompositions 
\begin{align*}
    \widetilde{\mathcal{Z}}=\widetilde{\mathcal{Z}}_1 \cup \widetilde{\mathcal{Z}}_2
\end{align*}
where each $\widetilde{\mathcal{Z}}_i$ is a union of irreducible components, 
 $\widetilde{\mathcal{Z}}_1$ corresponds to $y'=x'$, 
and $\widetilde{\mathcal{Z}}_2$ corresponds to $y'=\sigma(x')$. 
We have $\mathcal{Z}=\widetilde{\mathcal{Z}}_2$, and $\mathcal{Z}'$ is one of the irreducible components of $\widetilde{\mathcal{Z}}_2$. 

However, since $D \to C\times \mathcal{B}$ is \'etale and $C$ is smooth, 
the map $D \to \mathcal{B}$ is smooth and 
$\Delta(D) \subset D\times_{\mathcal{B}}D$ is a Cartier divisor. 
As a pull-back of the Cartier divisor, each irreducible component of 
$\widetilde{\mathcal{Z}}$ should have codimension at most one, which 
contradicts with (\ref{codim:Z}).

\emph{(cf.~\cite[Lemma~5.6]{TodaGL2})}\label{lem:inde}
The sheaf $\mathcal{P}_{\Delta 2}^{\sigma}$ is 
independent of a choice of an extension (\ref{ext:sigma}) up to an isomorphism.

\emph{(cf.~\cite[Lemma~5.7]{TodaGL2})}\label{lem:codimension}
Let $T$ be an irreducible variety and $T\to \mathcal{B}$ be a dominant map. 
The open immersion 
\begin{align}\label{jreg}
    j^{\mathrm{reg}}\colon \mathcal{H}^{\mathrm{reg}}_{T}:=T\times_{\mathcal{B}}\mathcal{H}^{\mathrm{reg}}
    \hookrightarrow \mathcal{H}_{T}     
\end{align}
    is an isomorphism in codimension one.

\label{lem:Vdelta}
There is a rank two sub-vector bundle (indeed a direct summand) 
\begin{align*}
  \mathcal{V}_{\Delta} \subset \mathcal{F}_{\Delta}
\end{align*}
which restricts to $\mathcal{V}_p \subset \mathcal{F}_c$ at $0 \in \Delta$.

Let
\begin{align*}
  \mathcal{E}_{\Delta} \in \operatorname{Coh}^{\heartsuit}(\mathcal{C}_{\Delta} \times_{\Delta} \mathcal{H}_{\Delta})
\end{align*}
be the pull-back of the universal one-dimensional sheaf $\mathcal{E}$ in
$\operatorname{Coh}(\mathcal{C} \times_{\mathcal{B}} \mathcal{H})$ given by the spectral construction.
By its construction, we have
\begin{align*}
  \pi_*\mathcal{E}_{\Delta} \cong (\pi')^*\mathcal{F}.
\end{align*}
Therefore we have
\begin{align*}
  \mathcal{F}_{\Delta}
  &\cong (\eta_D'')^*(g'')^*\pi_*\mathcal{E}_{\Delta} \\
  &\cong (\eta_D'')^*\pi_* (g')^*\mathcal{E}_{\Delta} \hookleftarrow
  (\eta_D'')^*\pi_{*} i_* g^* \mathcal{E}_{\Delta}.
\end{align*}
Here the last arrow is a split injection given by the decomposition into the open and closed
subsets $\mathcal{D} = \mathcal{D}_p \sqcup (\cdots)$.
The direct summand 
\begin{align}\label{def:Vdelta}
  \mathcal{V}_{\Delta}
  :=
  (\eta_D'')^*\pi_{*} i_* g^*\mathcal{E}_{\Delta},
\end{align}
is a rank two vector bundle since the map (\ref{map:D}) is a double 
cover, which restricts to $\mathcal{V}_p$ at $0\in \Delta$ by the construction. Therefore we obtain the lemma.

\label{prop:exact}
There is an exact sequence of vector bundles on $\Delta\times_{\mathcal{B}}\mathcal{H}^{\mathrm{reg}}$
\begin{align}\label{exact:jF}
    0\to j^{\mathrm{reg}*} \mathcal{P}_{\Delta 2}^{\sigma} \to j^{\mathrm{reg}*} \mathcal{V}_{\Delta}
    \otimes j^{\mathrm{reg}*} \mathcal{P}_{\Delta 1}\to j^{\mathrm{reg}*} \mathcal{P}_{\Delta 2}\to 0.
\end{align}
Here $j^{\mathrm{reg}}$ is the open immersion 
\begin{align*}
    j^{\mathrm{reg}}\colon \mathcal{H}^{\mathrm{reg}}_{\Delta}:=\Delta\times_{\mathcal{B}}\mathcal{H}^{\mathrm{reg}}
    \hookrightarrow \mathcal{H}_{\Delta}. 
\end{align*}

   We have the following diagram
   \begin{align*}
    \xymatrix{
& \mathcal{H}_{\Delta}^{\mathrm{reg}}  \ar[d]_-{\eta_D}  & \\
(\mathcal{D}_p)_{\Delta} \ar[d]_-{g} \ar@{}[rd]|\square &
(\mathcal{D}_{p})_{\Delta}\times_{\Delta}\mathcal{H}_{\Delta}^{\mathrm{reg}}
\ar[r]^-{q_{2}} \ar[l]_-{q_{1}} \ar[d]_-{g} &
\mathcal{H}_{\Delta}^{\mathrm{reg}} \\
\mathcal{C}_{\Delta} & \mathcal{C}_{\Delta}\times_{\Delta}\mathcal{H}_{\Delta}^{\mathrm{reg}} \ar[l]_-{p_1} \ar[ru]_-{p_2}
&
}
\end{align*}
Here the bottom arrows are projections. Let 
\begin{align}\label{E:pull}
\mathcal{E}_{\mathcal{D}}^{\mathrm{reg}}\in \operatorname{Coh}^{\heartsuit}((\mathcal{D}_p)_{\Delta}\times_{\Delta}\mathcal{H}_{\Delta}^{\mathrm{reg}}), \
\mathcal{E}^{\mathrm{reg}}_{\Delta}\in \operatorname{Coh}^{\heartsuit}(\mathcal{C}_{\Delta}\times_{\Delta}\mathcal{H}_{\Delta}^{\mathrm{reg}})
\end{align}
be the pull-back of the universal one-dimensional sheaf $\mathcal{E} \in \operatorname{Coh}^{\heartsuit}(\mathcal{C}\times_{\mathcal{B}}\mathcal{H})$. Note that (\ref{E:pull}) are line bundles by the definition of $\mathcal{H}^{\mathrm{reg}}$. 
Then by the construction and using (\ref{exact:EQ}), we have an isomorphism 
of line bundles on $\mathcal{H}_{\Delta}^{\mathrm{reg}}$
\begin{align}\notag
    j^{\mathrm{reg}*}\mathcal{P}_{\Delta 2}&=\det p_{2*}(p_1^*E_{\Delta}\otimes 
   \mathcal{E}^{\mathrm{reg}}_{\Delta})\otimes (\det p_{2*}p_1^*E_{\Delta})^{-1} \otimes (\det p_{2*}\mathcal{E}^{\mathrm{reg}}_{\Delta})^{-1}\otimes \det p_{2*}\mathcal{O}\\
   \notag &\cong j^{\mathrm{reg}*}\mathcal{P}_{\Delta 1}\otimes \det p_{2*}(p_1^* R_{\Delta}\otimes \mathcal{E}^{\mathrm{reg}}_{\Delta}).
\end{align}
We have isomorphisms 
\begin{align*}
    p_{2*}(p_1^* R_{\Delta}\otimes \mathcal{E}^{\mathrm{reg}}_{\Delta})&\cong 
    p_{2*}(g_{*}\eta_{D*}\mathcal{O}_{\mathcal{H}_{\Delta}^{\mathrm{reg}}}\otimes \mathcal{E}^{\mathrm{reg}}_{\Delta}) \\
    &\cong p_{2*}g_{*}(\eta_{D*}\mathcal{O}_{\mathcal{H}_{\Delta}^{\mathrm{reg}}}\otimes \mathcal{E}^{\mathrm{reg}}_{D}) \\
    &\cong \eta_D^* \mathcal{E}^{\mathrm{reg}}_{D}.
\end{align*}
Therefore we have 
\begin{align}\label{isom:P}
      j^{\mathrm{reg}*}\mathcal{P}_{\Delta 2} \cong j^{\mathrm{reg}*}\mathcal{P}_{\Delta 1} \otimes \eta_D^* \mathcal{E}^{\mathrm{reg}}_{D}.
\end{align}
In a similar way, we also have an isomorphism 
\begin{align}\label{isom:P2}
      j^{\mathrm{reg}*}\mathcal{P}_{\Delta 2}^{\sigma} \cong j^{\mathrm{reg}*}\mathcal{P}_{\Delta 1} \otimes (\sigma \circ \eta_D)^* \mathcal{E}^{\mathrm{reg}}_{D}.
\end{align}

Below we use the same notation as in (\ref{dia:delta2}) for the 
restricted diagram 
\begin{align}\label{dia:delta3}
    \xymatrix{
& \mathcal{H}_{\Delta}^{\mathrm{reg}} \ar[d]_-{\eta_D'} \ar[rd]^-{\eta_D''} \ar[ld]_-{\eta_D} & &\\
(\mathcal{D}_{p})_{\Delta}\times_{\Delta}\mathcal{H}_{\Delta}^{\mathrm{reg}} \ar@<-0.3ex>@{^{(}->}[r]^-{i} \ar[rd]_-{g} & \mathcal{D}_{\Delta}\times_{\Delta}\mathcal{H}_{\Delta}^{\mathrm{reg}} \ar[r]^-{\pi}\ar[d]_-{g'} \ar@{}[rd]|\square & D_{\Delta}\times_{\Delta}\mathcal{H}_{\Delta}^{\mathrm{reg}}  \ar[d]_-{g''} \ar[rd] & \\
& \mathcal{C}_{\Delta}\times_{\Delta}\mathcal{H}_{\Delta}^{\mathrm{reg}} \ar[r]^-{\pi} & C\times \mathcal{H}_{\Delta}^{\mathrm{reg}} \ar[r]^-{\pi'} &
C \times \mathcal{H}^{\mathrm{reg}}.       }
\end{align}
The composition of the maps in the diagram (\ref{dia:delta1})
\begin{align*}
    \pi_p \colon (\mathcal{D}_p)_{\Delta} \stackrel{i}{\hookrightarrow} \mathcal{D}_{\Delta} \stackrel{\pi}{\to} D_{\Delta}
\end{align*}
is a double cover with covering involution~$\sigma$. 
In the notation of (\ref{dia:delta1}), we have the decomposition
into the irreducible components 
\begin{align*}
    \pi_p^{-1}\eta_{D}''(\Delta)=\eta_D(\Delta)\cup (\sigma\circ \eta_D)(\Delta)
\end{align*}
whose intersection is a Cartier divisor on $\Delta$. Therefore by shrinking 
$\Delta$ if necessary, we have 
the exact sequence in $\operatorname{Coh}^{\heartsuit}((\mathcal{D}_p)_{\Delta})$
\begin{align*}
    0\to \sigma_{*}\eta_{D*}\mathcal{O}_{\Delta} \to \pi_p^* \pi_{p*}\eta_{D*}\mathcal{O}_{\Delta} \to \eta_{D*}\mathcal{O}_{\Delta} \to 0.
\end{align*}
By pulling it back to $(\mathcal{D}_p)_{\Delta}\times_{\Delta}\mathcal{H}_{\Delta}^{\mathrm{reg}}$
and applying $\otimes \mathcal{E}^{\mathrm{reg}}_{D}$, 
we obtain the exact sequence in $\operatorname{Coh}^{\heartsuit}((\mathcal{D}_p)_{\Delta}\times_{\Delta}\mathcal{H}_{\Delta}^{\mathrm{reg}})$
\begin{align*}
     0\to q_1^*\sigma_{*}\eta_{D*}\mathcal{O}_{\Delta} \otimes \mathcal{E}^{\mathrm{reg}}_{D}\to q_1^*\pi_p^* \pi_{p*}\eta_{D*}\mathcal{O}_{\Delta}\otimes \mathcal{E}^{\mathrm{reg}}_{D} \to q_1^*\eta_{D*}\mathcal{O}_{\Delta}\otimes \mathcal{E}^{\mathrm{reg}}_{D} \to 0. 
\end{align*}
Then applying $\pi_{p*}$ for the composition 
\begin{align*}
    \pi_p \colon (\mathcal{D}_p)_{\Delta}\times_{\Delta}\mathcal{H}_{\Delta}^{\mathrm{reg}}
    \stackrel{i}{\hookrightarrow} \mathcal{D}_{\Delta}\times_{\Delta}\mathcal{H}_{\Delta}^{\mathrm{reg}} \stackrel{\pi}{\to} D_{\Delta}\times_{\Delta}\mathcal{H}_{\Delta}^{\mathrm{reg}},
\end{align*}
we obtain 
the exact sequence in $\operatorname{Coh}^{\heartsuit}(D_{\Delta}\times_{\Delta}\mathcal{H}_{\Delta}^{\mathrm{reg}})$
\begin{align*}
0\to {}&
\pi_{p*}(q_1^*\sigma_{*}\eta_{D*}\mathcal{O}_{\Delta}
\otimes \mathcal{E}^{\mathrm{reg}}_{D}) \\
\to {}&
\pi_{p*}(q_1^*\pi_p^* \pi_{p*}\eta_{D*}\mathcal{O}_{\Delta}
\otimes \mathcal{E}^{\mathrm{reg}}_{D}) \\
\to {}&
\pi_{p*}(q_1^*\eta_{D*}\mathcal{O}_{\Delta}
\otimes \mathcal{E}^{\mathrm{reg}}_{D}) \to 0. 
\end{align*}

Note that by the definition of $\mathcal{V}_{\Delta}$ in (\ref{def:Vdelta}), we have 
\begin{align*}
    j^{\mathrm{reg}*}\mathcal{V}_{\Delta}=(\eta_D'')^* \pi_{p*}\mathcal{E}^{\mathrm{reg}}_{D}.
\end{align*}
Therefore we have 
\begin{align*}
    \pi_{p*}(q_1^*\pi_p^* \pi_{p*}\eta_{D*}\mathcal{O}_{\Delta}\otimes \mathcal{E}^{\mathrm{reg}}_{D})  &\cong \pi_{p*}(\pi_p^* \pi_{p*}\eta_{D*}\mathcal{O}_{\mathcal{H}_{\Delta}^{\mathrm{reg}}}\otimes \mathcal{E}^{\mathrm{reg}}_{D}) \\
    &\cong \pi_{p*}\eta_{D*}\mathcal{O}_{\mathcal{H}_{\Delta}^{\mathrm{reg}}}\otimes \pi_{p*}\mathcal{E}^{\mathrm{reg}}_{D}\\
    &\cong \eta_{D*}''(\eta_D'')^*\pi_{p*}\mathcal{E}^{\mathrm{reg}}_{D} \\
    &\cong \eta_{D*}''j^{\mathrm{reg}*}\mathcal{V}_{\Delta}.
\end{align*}
Similarly, we have 
\begin{align*}
   &\pi_{p*}(q_1^*\eta_{D*}\mathcal{O}_{\Delta}\otimes \mathcal{E}^{\mathrm{reg}}_{D}) \cong \eta_{D*}''\eta_D^* \mathcal{E}^{\mathrm{reg}}_{D}, \\
   & \pi_{p*}(q_1^*\sigma_*\eta_{D*}\mathcal{O}_{\Delta}\otimes \mathcal{E}^{\mathrm{reg}}_{D}) \cong \eta_{D*}''(\sigma \circ \eta_D)^* \mathcal{E}^{\mathrm{reg}}_{D}.
\end{align*} 

It follows that we obtain the exact sequence 
\begin{align*}
    0\to \eta^{''}_{D*}(\sigma \circ \eta_D)^* \mathcal{E}^{\mathrm{reg}}_{D} \to \eta^{''}_{D*}j^{\mathrm{reg}*}\mathcal{V}_{\Delta}\to \eta^{''}_{D*}\eta_D^{*}\mathcal{E}^{\mathrm{reg}}_{D} \to 0.
\end{align*}
Since $\eta_D''$ is a closed immersion (as it is a section of the projection),
we obtain the exact sequence in $\operatorname{Coh}^{\heartsuit}(\mathcal{H}_{\Delta}^{\mathrm{reg}})$
\begin{align*}
     0\to (\sigma \circ \eta_D)^* \mathcal{E}^{\mathrm{reg}}_{D} \to j^{\mathrm{reg}*}\mathcal{V}_{\Delta}\to \eta_D^{*}\mathcal{E}^{\mathrm{reg}}_{D}\to 0.
\end{align*}
By applying $j^{\mathrm{reg}*}\mathcal{P}_{\Delta 1} \otimes$ and using (\ref{isom:P}), (\ref{isom:P2}), we
obtain the desired exact sequence (\ref{exact:jF}).

\label{cor:CM}
    The exact sequence (\ref{exact:jF}) extends to a left exact sequence of maximal Cohen--Macaulay 
    sheaves on $\mathcal{H}_{\Delta}$
    \begin{align}\label{extend:CM}
        0\to \mathcal{P}_{\Delta 2}^{\sigma}\to \mathcal{V}_{\Delta}\otimes \mathcal{P}_{\Delta 1}
        \to \mathcal{P}_{\Delta 2}.
    \end{align}

\label{lem:nodal}
If $p\in \mathcal{C}_b$ is a nodal singularity, the 
sequence (\ref{extend:CM}) is also right exact. In particular, the sequence (\ref{extend:CM2}) is an exact sequence.

    The assumption on $\mathcal{C}_b$ implies that 
    $m_p=2$ and 
    the sheaf $E'$ on $\mathcal{C}_b$ is a line bundle at $p$. Let $\mathcal{C}_{\Delta}'\subset \mathcal{C}_{\Delta}$ be an open neighborhood of $p \in \mathcal{C}_b=\mathcal{C}_{\Delta}\times_{\Delta}0$ such that 
    $E_t':=E_{\Delta}'|_{\mathcal{C}_{\Delta}\times_{\Delta}t}$ is a line bundle on $\mathcal{C}_{\Delta}'\times_{\Delta} t$
    for all $t\in \Delta$. 
    Then there is a morphism 
    \begin{align}\label{mor:circ}
\mathcal{C}_{\Delta}' \to \mathcal{H}_{\Delta}
    \end{align}
    sending $x\in \mathcal{C}_{\Delta}'\times_{\Delta}t$ 
    to $E_x \in \operatorname{Coh}^{\heartsuit}(\mathcal{C}_t)$ which fits into 
    the unique non-trivial extension (up to isomorphism)
    \begin{align*}
        0\to E_t' \to E_x \to \mathcal{O}_x \to 0. 
    \end{align*}
In the diagram (\ref{dia:eta}), note that $\eta(0)=p\in \mathcal{C}_{\Delta}'$. 
Therefore by shrinking $\Delta$ if necessary we may assume that 
    $\eta \colon \Delta \to \mathcal{C}_{\Delta}$ factors through 
    $\eta \colon \Delta \to \mathcal{C}_{\Delta}'$.
    Then from the diagram (\ref{dia:eta}), 
    the map $\eta_D$ factors as 
    \begin{align*}
        \eta_D \colon \Delta \to (\mathcal{D}_p)_{\Delta}':=(\mathcal{D}_p)_{\Delta}\times_{\mathcal{C}_{\Delta}}\mathcal{C}_{\Delta}'.
        \end{align*}
The above situation is summarized in the following diagram 
    \begin{align}\label{dia:Dpprime}
        \xymatrix{
