Since $A\in \operatorname{L}(\mathcal{H}(w)^{\mathrm{ss}})_{-\chi'}$, the $\lambda$-weights
of $A_b|_{\mathcal{S}}$ are contained in 
\begin{align}\label{wt:A}
    \left[\frac{1}{2}c_1(\lambda^*\mathbb{L}_{\mathcal{H}_T(w)^{\mathrm{ss}}}^{<0}), 
    \frac{1}{2}c_1(\lambda^*\mathbb{L}_{\mathcal{H}_T(w)^{\mathrm{ss}}}^{>0})
    \right]+c_1(\lambda^* \delta_{-\chi'}).
\end{align}
Therefore 
by noting that $\chi'=\chi+r(r-1)(g-1)$ and Lemma~\ref{lem:Gmwt:L}, 
a $\lambda$-weight of $A_b|_{\mathcal{S}}$
is at most
\begin{align}\label{wt:1}
    (g-1)\sum_{1\leqslant j<j' \leqslant a}R_j R_{j'}(\lambda_j-\lambda_{j'})-\frac{\chi}{r}\sum_{j=1}^a R_j \lambda_j-(r-1)(g-1)\sum_{j=1}^a R_j\lambda_j.
\end{align}
The $\lambda$-weight of 
$\det \mathbb{L}_{\mathcal{S}/\mathcal{H}_T(w)^{\mathrm{ss}}}$
is \begin{align}\label{wt:2}
c_1(\lambda^*\mathbb{L}_{\mathcal{H}_T(w)^{\mathrm{ss}}}^{<0})=(2g-2)\sum_{1\leqslant j'<j \leqslant a}R_j R_{j'}(\lambda_j-\lambda_{j'}).
\end{align}

We will study $\lambda$-weights of $\mathcal{V}_M|_{\mathcal{S}}$. 
Let 
\begin{align*}
    N_i \subset \mathrm{Sing}(C_i)
\end{align*}
be the subset on which $M_i$ is not locally free. 
By Lemma~\ref{lem:Qp}, we have the exact sequence 
\begin{align}\label{ex:LM1}
    0\to L_i \to M_i \to \bigoplus_{p\in N_i}Q_p \to 0
\end{align}
where $L_i$ is a line bundle on $C_i$ and $Q_p \cong \mathcal{O}_{W_p}$ for 
a closed subscheme $W_p \hookrightarrow Z_p$ with length $1\leqslant n_p \leqslant m_p/2$, where $Z_p$ is given in (\ref{def:Zp}). Moreover we have the exact sequence 
\begin{align}\label{ex:LM2}
    0\to L \to \bigoplus_{i=1}^k L_i \to \bigoplus_{p\in C_i \cap C_{i'}, i<i'}Q_p \to 0
\end{align}
where $L$ is a line bundle on $\mathcal{C}_b$ obtained by gluing $L_i$ at each intersection 
points of $C_i \cap C_{i'}$; it satisfies that 
$L|_{C_i}\cong L_i$ and $Q_p \cong \mathcal{O}_{Z_p}$ 
for each $p\in C_i \cap C_{i'}$. 
Then we have 
\begin{align*}
    \mathcal{V}_M \cong \mathcal{P}_L \otimes \bigotimes_{p\in N_i, 1\leqslant i\leqslant k}\mathcal{V}_p^{\otimes n_p} \otimes 
    \bigotimes_{p\in C_i \cap C_{i'}, i<i'}\mathcal{V}_p^{\otimes m_p/2}.
\end{align*}
Here note that $m_p$ is even if $p$ is an intersection of irreducible components. By Lemma~\ref{lem:PLGm}, 
a $\lambda$-weight of 
$\mathcal{P}_L$ is given by 
\begin{align}\label{wt:3}
\sum_{j=1}^a l_j \lambda_j, \ l_j:=\deg_{D_j}(L|_{D_j})
\end{align}
Since $D_j=C_{1j}+\cdots+C_{kj}$ and $L|_{C_{ij}}\cong L_i|_{C_{ij}}$, 
by Lemma~\ref{lem:add} we have 
\begin{align}\label{lj}
l_j=\deg_{C_{1j}}(L_1|_{C_{1j}})+\deg_{C_{2j}}(L_2|_{C_{2j}})+\cdots+ \deg_{C_{kj}}(L_k|_{C_{kj}}).
\end{align}

A $\lambda$-weight of $\bigotimes_{p\in N_i, 1\leqslant i\leqslant k}\mathcal{V}_p^{\otimes n_p}$
is of the form 
\begin{align}\label{wt:4}
    \sum_{i=1}^k \sum_{p\in N_i} (a_p\lambda_{\alpha(p)}+b_p\lambda_{\beta(p)}), 
\end{align}
where $p \in C_{i\alpha(p)}\cap C_{i\beta(p)}$ for $1\leqslant \alpha(p) \leqslant \beta(p) \leqslant a$, 
and $a_p+b_p=n_p$ with $a_p, b_p\geqslant 0$. 

Since we have 
\begin{align*}
    C_{i} \cap C_{i'}=\bigcup_{1\leqslant j, j' \leqslant a} C_{ij} \cap C_{i'j'},
\end{align*}
and (noting that $m_p/2$ is the intersection multiplicity at $p\in C_{ij} \cap C_{i' j'}$)
\begin{align*}
    C_{ij} \cdot C_{i' j'}=\sum_{p\in C_{ij} \cap C_{i' j'}}\frac{m_p}{2}=r_{ij} r_{i' j'}(2g-2), 
\end{align*}
a $\lambda$-weight of $\bigotimes_{p\in C_i \cap C_{i'}, i<i'}\mathcal{V}_p^{\otimes m_p/2}$
is of the form 
\begin{align}\label{wt:5}
    \sum_{1\leqslant i<i' \leqslant k} \sum_{1\leqslant j, j' \leqslant a}(c_{i i' j j'}\lambda_j+
    d_{i i' j j'}\lambda_{j'})
\end{align}
where $c_{i i' j j'},  d_{i i' j j'}$ satisfy 
\begin{align}\label{cond:bc}
    c_{i i' j j'}\geqslant 0, \ d_{i i' j j'} \geqslant 0, \  c_{i i' j j'}+d_{i i' j j'}=r_{ij} r_{i' j'}(2g-2).
\end{align}
By (\ref{wt:1}), (\ref{wt:2}), (\ref{wt:3}), (\ref{wt:4}), (\ref{wt:5}), 
a $\lambda$-weight of (\ref{show:zero}) is at most 
\begin{align}\label{wt:final}
&(g-1)\sum_{1\leqslant j<j' \leqslant a}R_j R_{j'}(\lambda_j-\lambda_{j'})-\frac{\chi}{r}\sum_{j=1}^a R_j \lambda_j
 -(r-1)(g-1)\sum_{j=1}^a R_j \lambda_j 
\\
&\notag +(2g-2)\sum_{1\leqslant j'<j \leqslant a}R_j R_{j'}(\lambda_j-\lambda_{j'})
+\sum_{j=1}^a l_j \lambda_j \\
&\notag + \sum_{i=1}^k \sum_{p\in N_i} (a_p\lambda_{\alpha(p)}+b_p\lambda_{\beta(p)})
+ \sum_{1\leqslant i<i' \leqslant k} \sum_{1\leqslant j, j' \leqslant a}(c_{i i' j j'}\lambda_j+
    d_{i i' j j'}\lambda_{j'}).
\end{align}
\begin{sstep}
A $\lambda$-weight (\ref{wt:final}) is negative. 
\end{sstep}
Since $\deg \pi_{*}M=\chi$, by the formula (\ref{formula:deg}) we have 
\begin{align*}
    \deg_{\mathcal{C}_b}(M)=\chi'=\chi+r(r-1)(g-1).
\end{align*}
By (\ref{ex:LM1}), (\ref{ex:LM2}), we have 
\begin{align*}
    \deg_{\mathcal{C}_b}(M)
    =\deg_{\mathcal{C}_b}(L)+\sum_{i=1}^k \sum_{p\in N_i}n_p
    +\sum_{1\leqslant i<i'\leqslant k}\sum_{1\leqslant j, j' \leqslant a}r_{ij} r_{i'j'}(2g-2).
\end{align*}
Using Lemma~\ref{lem:add}, it follows that 
\begin{align}\label{sum:l:lambda}
    &l_1+\cdots+l_a+\sum_{i=1}^k \sum_{p\in N_i}n_p +\sum_{1\leqslant i<i'\leqslant k}\sum_{1\leqslant j, j' \leqslant a}r_{ij} r_{i'j'}(2g-2) \\
    &\notag =\chi+r(r-1)(g-1).
\end{align}
By (\ref{sum:l:lambda}), the weight (\ref{wt:final}) is of the form 
\begin{align*}
    \sum_{j=1}^a \alpha_j \lambda_j, \ \alpha_1+\cdots+\alpha_a=0.
\end{align*}
Therefore it is written as 
\begin{align*}
    \sum_{m=1}^{a-1} \beta_m (\lambda_m-\lambda_{m+1}), \ \beta_m=\sum_{j=1}^m \alpha_j.
\end{align*}
Since $\lambda_m-\lambda_{m+1}>0$, it is enough to show that $\beta_m<0$. 

For a subset $J\subset \{1, \ldots, a\}$, 
we write 
\begin{align*}r_{iJ}:=\sum_{j\in J}r_{ij}, \ l_{J}:=\sum_{j\in J}l_j, \ 
R_J:=\sum_{j\in J} R_j.
\end{align*}
Let $J_m=\{1, \ldots, m\} \subset \{1, \ldots, a\}$, and $J_m^{\circ}$ its complement. 
A direct computation shows that 
\begin{align*}
    \beta_m&=-(g-1)R_{J_m}R_{J_m^{\circ}}-\frac{\chi}{r}R_{J_m}-(r-1)(g-1)R_{J_m}+l_{J_m} \\
    &+\sum_{i=1}^k\left(\sum_{p\in N_i, \alpha(p)\leqslant m}a_p+\sum_{p\in N_i, \beta(p)\leqslant m}b_p\right)+B_{J_m}.
\end{align*}
Here $B_{J_m}$ is given by 
\begin{align*}
    B_{J_m}=\sum_{i<i'}\left(\sum_{j\leqslant m, j'\leqslant a}c_{i i' j j'}+\sum_{j\leqslant a, j'\leqslant m}d_{i i' j j'}\right).
\end{align*}
By the condition (\ref{cond:bc}), 
we have 
\begin{align*}
    B_{J_m} \leqslant (2g-2)\sum_{i<i'}(r_{iJ_m}r_{i'J_m}+r_{iJ_m}r_{i' J_m^{\circ}}+r_{i J_m^{\circ}}r_{i' J_m}).
\end{align*}

For a subset $J\subset \{1, \ldots, a\}$, we have the 
exact sequence of the form 
\begin{align*}
    0\to M_i' \to M_i \to M_i|_{C_{iJ}}^{\mathrm{free}} \to 0.
\end{align*}
Here $C_{iJ}:=\cup_{j\in J} C_{ij}$. 
By the semistability of $M_i$, we have 
\begin{align}\label{wt:M}
    \frac{\deg \pi_{*}M_i'}{r_{iJ^{\circ}}} \leqslant \frac{\chi_i}{r_i}.
\end{align}
Similarly to (\ref{ex:E2}), we have the 
