\end{align*}
By multiplying $r_{iJ^{\circ}}$ and replacing $J$ with $J^{\circ}$ and taking the sum over $1\leqslant i \leqslant k$, 
from (\ref{lj}) we have 
\begin{align}\label{wt:lJ}
    l_J \leqslant \sum_{i=1}^k \left(\frac{\chi_i}{r_i}r_{iJ}+r_{iJ}(r_{iJ}-1)(g-1)+r_{iJ}r_{iJ^{\circ}}(2g-2)-\sum_{p\in N_i \cap C_{iJ}}n_p   \right).
\end{align}
It follows that 
\begin{align*}
    \beta_m \leqslant & -(g-1)R_{J_m}R_{J_m^{\circ}}-\frac{\chi}{r}R_{J_m}-(r-1)(g-1)R_{J_m} \\
    &+\sum_{i=1}^k \left(\frac{\chi_i}{r_i}r_{iJ_m}+r_{iJ_m}(r_{iJ_m}-1)(g-1)+r_{iJ_m}r_{iJ_m^{\circ}}(2g-2)-\sum_{p\in N_i \cap C_{iJ_m}}n_p  \right) \\
    &+\sum_{i=1}^k \left(\sum_{p\in N_i, \alpha(p)\leqslant m}a_p+\sum_{p\in N_i, \beta(p)\leqslant m}b_p\right) \\
    &+(2g-2)\sum_{i<i'}(r_{iJ_m}r_{i'J_m}+r_{iJ_m}r_{i' J_m^{\circ}}+r_{i J_m^{\circ}}r_{i' J_m}).
\end{align*}
In the right-hand side, a straightforward computation shows that the terms which are divisible by $(g-1)$
