\end{align*}

\begin{align}\label{ineq:beta}
    \beta_m &\leqslant -\frac{\chi}{r}R_{J_m}+\sum_{i=1}^k \left(\frac{\chi_i}{r_i}r_{iJ_m}-
    \sum_{p\in N_i \cap C_{iJ_m}}n_p
  +\sum_{p\in N_i, \alpha(p)\leqslant m}a_p+\sum_{p\in N_i, \beta(p)\leqslant m}b_p  \right) \\
    &\notag \leqslant -\frac{\chi}{r}R_{J_m}+\sum_{i=1}^k \frac{\chi_i}{r_i}r_{iJ_m}.
\end{align}

\begin{align*}
    \frac{1}{R_{J_m}}\sum_{i=1}^k \frac{\chi_i}{r_i}r_{i J_m}=\frac{\sum_{j\leqslant m}R_j q_j}{\sum_{j\leqslant m}R_j}<\frac{\sum_{j\leqslant a}R_j q_j}{\sum_{j\leqslant a}R_j}=\frac{\chi}{r}.
\end{align*}

There is a sequence of closed immersions 
\begin{align*}
   \mathcal{S}=\mathcal{S}^{(1)} \hookrightarrow \mathcal{S}^{(2)} \hookrightarrow \mathcal{S}^{(3)} \hookrightarrow 
    \cdots \hookrightarrow \mathcal{H}_T(w)^{\mathrm{ss}}
\end{align*}
where each $\mathcal{S}^{(n)}$ is the $n$-th infinitesimal thickening of $\mathcal{S}$ in $\mathcal{H}_T(w)^{\mathrm{ss}}$, 
whose structure sheaves fit into distinguished triangles 
\begin{align*}
    \mathrm{Sym}^{n}(\mathbb{L}_{\mathcal{S}/\mathcal{H}_T(w)^{\mathrm{ss}}}[-1]) \to \mathcal{O}_{\mathcal{S}^{(n+1)}} \to \mathcal{O}_{\mathcal{S}^{(n)}}.
\end{align*}
Then $\mathcal{H}om_{\mathcal{H}_T(w)^{\mathrm{ss}}}(\mathcal{O}_{\mathcal{S}^{(n)}}, A_b \otimes \mathcal{V}_M)$ is filtered by 
\begin{align}\label{filt:negative}
(A_b \otimes \mathcal{V}_M)|_{\mathcal{S}} \otimes \det \mathbb{L}_{\mathcal{S}/\mathcal{H}_T(w)^{\mathrm{ss}}}[-d]\otimes\mathrm{Sym}^i(\mathbb{L}_{\mathcal{S}/\mathcal{H}_T(w)^{\mathrm{ss}}}[-1])^{\vee}  
\end{align}
for $0\leqslant i\leqslant n-1$. The first two factors have negative 
$\lambda$-weights by Lemma~\ref{lem:nweight}. Also since $\mathcal{S} \subset \mathcal{H}_T(w)^{\mathrm{ss}}$ is a $\Theta$-stratum, the object 
$\mathbb{L}_{\mathcal{S}/\mathcal{H}_T(w)^{\mathrm{ss}}}$ has positive $\lambda$-weights, 
see~\cite[Lemma~1.3.2]{HalpK32}. Therefore the last factor of (\ref{filt:negative}) has also negative $\lambda$-weights, and 
we conclude that (\ref{filt:negative}) has negative 
$\lambda$-weights. 

Now for the good moduli space map 
$r_T \colon \mathcal{H}_T(w)^{\mathrm{ss}} \to \mathrm{H}_T(w)^{\mathrm{ss}}$, we have 
the commutative diagram 
\begin{align*}
    \xymatrix{
    \mathcal{H}_T(w)^{\mathrm{ss}} \ar[rr]^-{r_T} & &\mathrm{H}_T(w)^{\mathrm{ss}} \\
    \mathcal{S} \ar@<-0.3ex>@{^{(}->}[u] \ar[r]^-{g_T} & \mathcal{Z} \ar[r]^-{g_T'} & Z. \ar[u]
    }
\end{align*}
Here the top and the right bottom horizontal arrows are good moduli space morphisms.  
Since (\ref{filt:negative}) has negative $\lambda$-weights, 
its push-forward $g_{T*}$ has also negative $\lambda$-weights; this follows from~\cite[Lemma~1.5.6]{HalpK32} which says that $g_{T*}$ does not increase the maximum $\lambda$-weights. 
Since the push-forward $g_{T*}'$ to the good moduli space $Z$ extracts the weight-zero
part along the stabilizer $\mathbb G_m$ on $\mathcal{Z}$, an object 
$E \in \operatorname{QCoh}(\mathcal{Z})$ with strictly negative $\lambda$-weights satisfies $g_{T*}'E=0$. 
Therefore from the above commutative diagram, we have 
\begin{align}\label{vanish:rt}
    r_{T*}\mathcal{H}om_{\mathcal{H}_T(w)^{\mathrm{ss}}}(\mathcal{O}_{\mathcal{S}^{(n)}}, A_b \otimes \mathcal{V}_M)=0. 
\end{align}

Note that we have the isomorphisms in $\operatorname{QCoh}(\mathcal{H}_T(w)^{\mathrm{ss}})$
\begin{align*}
\Gamma_{\mathcal{S}}(A_b\otimes \mathcal{V}_M)&\cong 
\operatorname*{colim}_{\mathcal{S} \subset \mathcal{S}'}
    \mathcal{H}om_{\mathcal{H}_T(w)^{\mathrm{ss}}}(\mathcal{O}_{\mathcal{S}'}, A_b \otimes \mathcal{V}_M) \\
    &\cong \operatorname*{colim}_{n\geqslant 0}\mathcal{H}om_{\mathcal{H}_T(w)^{\mathrm{ss}}}(\mathcal{O}_{\mathcal{S}^{(n)}}, A_b \otimes \mathcal{V}_M).
    \end{align*}
    Since $r_{T*}$ is continuous on $\operatorname{QCoh}$, by (\ref{vanish:rt}) we obtain the vanishing 
    \begin{align*}
        r_{T*}\Gamma_{\mathcal{S}}(A_b \otimes \mathcal{V}_M)=0.
    \end{align*}
Therefore by taking the global section over $\mathrm{H}_T(w)^{\mathrm{ss}}$, we obtain the vanishing (\ref{vanish:Gamma}).

We consider the following closed substack 
\begin{align*}
    \mathcal{S}_{\geqslant k}:=\mathcal{S}_k \sqcup \cdots \sqcup \mathcal{S}_N \subset \mathcal{H}_T(w)^{\mathrm{ss}}.
\end{align*}

We replace the argument of Proposition~\ref{prop:vanishing} to 
the $\Theta$-stratum 
\begin{align*}
    \mathcal{S}_k \subset \mathcal{H}_T(w)^{\mathrm{ss}}_{\leqslant k}:=\mathcal{H}_T(w)^{\mathrm{ss}}\setminus \mathcal{S}_{\geqslant k+1}
\end{align*}
to conclude that 
\begin{align}\label{vanish:Gamma2}
  \Gamma(\mathcal{H}_T(w)^{\mathrm{ss}}_{\leqslant k}, \Gamma_{\mathcal{S}_k}((A_b \otimes \mathcal{V}_M)|_{\mathcal{H}_T(w)_{\leqslant k}^{\mathrm{ss}}}))=0. 
\end{align}
We have the distinguished triangle in $\operatorname{QCoh}(\mathcal{H}_T(w)^{\mathrm{ss}})$
\begin{align*}
    \Gamma_{\mathcal{S}_{\geqslant k+1}}(A_b\otimes \mathcal{V}_M) \to  \Gamma_{\mathcal{S}_{\geqslant k}}(A_b\otimes \mathcal{V}_M)
    \to (j_{\leqslant k})_{*}\Gamma_{\mathcal{S}_k}((A_b \otimes \mathcal{V}_M)|_{\mathcal{H}_T(w)^{\mathrm{ss}}_{>k}}).
\end{align*}
Here $j_{\leqslant k} \colon \mathcal{H}_T(w)^{\mathrm{ss}}_{\leqslant k} \hookrightarrow \mathcal{H}_T(w)^{\mathrm{ss}}$ is the open immersion. It follows that 
we have the isomorphism 
\begin{align*}
    \Gamma(\mathcal{H}_T(w)^{\mathrm{ss}},  \Gamma_{\mathcal{S}_{\geqslant k+1}}(A_b\otimes \mathcal{V}_M)) \stackrel{\cong}{\to} 
    \Gamma(\mathcal{H}_T(w)^{\mathrm{ss}}, \Gamma_{\mathcal{S}_{\geqslant k}}(A_b\otimes \mathcal{V}_M)).
\end{align*}
Therefore by (\ref{vanish:Gamma}) and the induction on $k$, we conclude (\ref{vanish:Gamma2.5}).

\label{lem:alphagen}
Suppose that for any non-empty proper subset $K\subset \{1, \ldots, m\}$, 
we have 
\begin{align}\label{cond:K}
    \sum_{a\in K}r^{(a)}\left( \frac{\chi_{i(a)}}{r_{i(a)}}-\frac{\chi}{r} \right)=0 \quad \Rightarrow \quad \sum_{a\in K} r^{(a)} \alpha^{(a)} \neq 0.
\end{align}
Then there are no strictly $h_T^{\varepsilon\dag}$-semistable sheaves, i.e.\ 
\begin{align}\label{ss=st}
    \mathcal{H}_T(w)^{\varepsilon \dag \text{-ss}}=\mathcal{H}_T(w)^{\varepsilon \dag \text{-st}}.
\end{align}

Suppose that there is a strictly $h_T^{\varepsilon\dag}$-semistable sheaf. 
Then there is a non-empty proper subset $K\subset \{1, \ldots, m\}$ and 
$w'\in \mathbb{Z}$ with an equality 
\begin{align}\label{equal:ra}
    \frac{w'}{\sum_{a\in K}r^{(a)}\left(1+\left(\frac{\chi_i}{r_i}-\frac{\chi}{r}  \right)\varepsilon +\alpha^{(a)}\varepsilon^2\right)}
    =\frac{w}{r}
\end{align}
for $0<\varepsilon \ll 1$. By setting $\varepsilon \to 0$, we obtain 
\begin{align*}
    \frac{w'}{\sum_{a\in K}r^{(a)}}
    =\frac{w}{r}.
\end{align*}
By substituting into (\ref{equal:ra}), and using the $w>0$ assumption, 
we obtain 
\begin{align*}
     \sum_{a\in K}r^{(a)}\left( \frac{\chi_{i(a)}}{r_{i(a)}}-\frac{\chi}{r} \right)+\varepsilon\cdot \sum_{a\in K} r^{(a)} \alpha^{(a)} =0
\end{align*}
for $0<\varepsilon \ll 1$. This does not happen precisely when (\ref{cond:K}) 
is satisfied.

We denote by 
\begin{align*}
    \mathcal{H}_T(w)^{\mathrm{ss}}=
    \mathcal{H}_T(w)^{\varepsilon\dag\text{-ss}} \sqcup 
    \mathcal{S}_1^{\dag} \sqcup \cdots \sqcup \mathcal{S}_{N'}^{\dag} 
\end{align*}
the Harder--Narasimhan stratification with respect to the $h_T^{\varepsilon \dag}$-stability, 
with center $\mathcal{S}_i^{\dag} \to \mathcal{Z}_i^{\dag}$.

We write $\mathcal{S}^{\dag}=\mathcal{S}_{N'}^{\dag}$ and $\mathcal{Z}^{\dag}=\mathcal{Z}_{N'}^{\dag}$. 
   Let $\lambda \colon B\mathbb{G}_m \to \mathcal{Z}^{\dag}$ be a map corresponding to the HN filtration with respect to the $h_T^{\varepsilon\dag}$-stability; it is 
   given by 
   \begin{align*}
       \lambda \colon \mathrm{pt} \mapsto E_1 \oplus \cdots \oplus E_a
   \end{align*}
   with $\mathbb{G}_m$-weights $(\lambda_1, \ldots, \lambda_a)$
   for $\lambda_1>\cdots>\lambda_a$, 
    each $E_i$ is $h_T^{\varepsilon\dag}$-semistable such that 
   \begin{align*}
       \mu^{\varepsilon \dag}(E_1)>\cdots>\mu^{\varepsilon \dag}(E_a), \ \mu^0(E_1)=\cdots=\mu^0(E_a)
   \end{align*}
   for $0<\varepsilon \ll 1$. 
   Then we have 
   \begin{align}\label{ineq:weak}
       \mu^{\varepsilon}(E_1) \geqslant \cdots \geqslant \mu^{\varepsilon}(E_a).
   \end{align}

   We now apply the argument of the proof of Lemma~\ref{lem:nweight}, by replacing 
   the inequality (\ref{slope:cond}) with the weaker one (\ref{ineq:weak}). 
   Using the notation in Lemma~\ref{lem:nweight}, we have 
   the inequality slightly weaker than (\ref{ineq:q})
   \begin{align}\label{ineq:q2}
   q_1 \leqslant \cdots \leqslant q_a. 
   \end{align}

   On the other hand, for $A_b=\mathcal{O}_{\mathcal{H}_b(w)^{\mathrm{ss}}}$, 
   its restriction to $\mathcal{S}^{\dag}$ has $\lambda$-weight zero. 
   Therefore we obtain the upper bound of $\beta_m$ in (\ref{ineq:beta})
   without the contributions from (\ref{wt:1}). 
   Since we have 
   \begin{align*}
       \sum_{j<j'}R_j R_{j'}(\lambda_j-\lambda_{j'})=\sum_{m=1}^{a-1}R_{J_m}R_{J_m^{\circ}}(\lambda_m-\lambda_{m+1})
   \end{align*}
   it follows that we have the inequality slightly better than (\ref{ineq:beta})
   \begin{align*}
   \beta_m &\leqslant 
    -\frac{\chi}{r}R_{J_m}+\sum_{i=1}^k \frac{\chi_i}{r_i}r_{iJ_m}
    -(g-1)R_{J_m}R_{J_m^{\circ}} \\&\leqslant -(g-1)R_{J_m}R_{J_m^{\circ}}.
    \end{align*}
    Here the second inequality follows from (\ref{ineq:q2}). 

    Since $g\geqslant 2$, we have $\beta_m\leqslant 0$ for all $1\leqslant m \leqslant a-1$, 
    and $\beta_m<0$ for some $1\leqslant m\leqslant a-1$.
    Therefore the $\lambda$-weights of $\mathcal{V}_M \otimes \det \mathbb{L}_{\mathcal{S}^{\dag}/\mathcal{H}_T(w)^{\mathrm{ss}}}$ are negative 
    and we obtain the vanishing (\ref{vanish:gammaO}) for $k=1$ as in the proof of Proposition~\ref{prop:vanishing}. Then the lemma follows as in 
    the argument of Proposition~\ref{prop:vanish2}.

\label{thm:PhiO}
We have 
\begin{align*}
\Phi(\mathcal{O}_{\mathcal{H}(w)^{\mathrm{ss}}})\in j_{!}\operatorname{L}(\mathcal{H}(\chi_0)^{\mathrm{ss}})_{w'}.
\end{align*}   
Here $j_{!}$ is the fully-faithful left adjoint of the pull-back $j^*$
for the open immersion $j \colon \mathcal{H}(\chi_0)^{\mathrm{ss}} \hookrightarrow \mathcal{H}(\chi_0)$
\begin{align*}j_{!} \colon \operatorname{L}(\mathcal{H}(\chi_0)^{\mathrm{ss}})_{w'} \hookrightarrow \operatorname{L}(\mathcal{H}(\chi_0))_{w'}.
\end{align*}

We divide the proof into 2 steps.
\begin{ssstep}
The result on the semistable locus. 
\end{ssstep}
   We first show that 
   \begin{align}\label{Phi:rest}
\Phi(\mathcal{O}_{\mathcal{H}(w)^{\mathrm{ss}}})|_{\mathcal{H}(\chi_0)^{\mathrm{ss}}} \in \operatorname{L}(\mathcal{H}(\chi_0)^{\mathrm{ss}})_{w'}.
   \end{align}
Let $\nu$ be a map 
\begin{align*}
    \nu \colon B\mathbb{G}_m \to \mathcal{H}_T(\chi_0)^{\mathrm{ss}}, \ 
    \mathrm{pt} \mapsto M=M_1 \oplus \cdots \oplus M_k
\end{align*}
over $b\in \mathcal{B}$ as in (\ref{map:v2}); since $M$ is semistable, 
each $M_i\in \operatorname{Coh}^{\heartsuit}(\mathcal{C}_b)$ is semistable with 
\begin{align}\label{chir}
    \frac{\chi_1}{r_1}=\cdots=\frac{\chi_k}{r_k}, 
\end{align}
where $r_i=\operatorname{rank}(\pi_{*}M_i)$ and $\chi_i=\deg \pi_{*}M_i$. 
We take an \'{e}tale neighborhood $(T, 0)\to (\mathcal{B}, b)$ and an ample $\mathbb{Q}$-divisor 
$h_T^{\varepsilon\dag}$ as in (\ref{hTeps}). 
Note that by the condition (\ref{chir}), the coefficient of $\varepsilon$ vanishes in (\ref{hTeps}), and 
$h_T^{\varepsilon\dag}$ can be taken to be independent of $\nu$ over $b$; namely 
for a choice of $(\alpha^{(a)})_{1\leqslant a\leqslant m}$ as in (\ref{choice:alpha})
satisfying the condition in Lemma~\ref{lem:alphagen}, 
we take $h_T^{\varepsilon\dag}$ such that 
\begin{align}\label{hT:indep}
    h_T^{\varepsilon\dag} \cdot \mathcal{C}_b^{(a)}=r^{(a)}(1+\alpha^{(a)}\varepsilon^2).
\end{align}

Let $\Phi_T^{\varepsilon\dag}$ be the functor 
\begin{align*}
  \Phi_T^{\varepsilon\dag}\colon \operatorname{Coh}(\mathcal{H}_T(w)^{\varepsilon\dag\text{-ss}})_0 \to 
  \operatorname{Coh}(\mathcal{H}_T(\chi_0)^{\mathrm{ss}})_{w'}
\end{align*}
defined by the kernel object 
\begin{align}\label{PTvd}
\mathcal{P}_T^{\varepsilon\dag}:=
    \mathcal{P}_T|_{\mathcal{H}_T(w)^{\varepsilon\dag\text{-ss}}\times_T \mathcal{H}_T(\chi_0)^{\text{ss}}} \in \operatorname{Coh}(\mathcal{H}_T(w)^{\varepsilon\dag\text{-ss}}\times_T \mathcal{H}_T(\chi_0)^{\text{ss}}).
\end{align}
Here $\mathcal{P}_T$ is the pull-back of the Arinkin sheaf (\ref{P:pullT}). 
From the distinguished triangle 
\begin{align*}
\Gamma_{\mathcal{S}^{\dag}_{\leqslant N'}}
\bigl(\mathcal{P}_T|_{\mathcal{H}_T(w)^{\text{ss}}\times_T \mathcal{H}_T(\chi_0)^{\text{ss}}}\bigr)
\to {}& \mathcal{P}_T|_{\mathcal{H}_T(w)^{\text{ss}}\times_T \mathcal{H}_T(\chi_0)^{\text{ss}}} \\
\to {}& \mathcal{P}_T|_{\mathcal{H}_T(w)^{\varepsilon\dag\text{-ss}}\times_T
\mathcal{H}_T(\chi_0)^{\text{ss}}},
\end{align*}
after pushing forward to $\mathcal{H}_T(\chi_0)^{\mathrm{ss}}$, we obtain, in
\[
\operatorname{Coh}(\mathcal{H}_T(\chi_0)^{\mathrm{ss}}),
\]
a distinguished triangle of the form
\begin{align*}
K\to {}&
\Phi_T(\mathcal{O}_{\mathcal{H}_T(w)^{\mathrm{ss}}})|_{\mathcal{H}_T(\chi_0)^{\text{ss}}} \\
\to {}&
\Phi_T^{\varepsilon\dag}(\mathcal{O}_{\mathcal{H}_T(w)^{\varepsilon\dag\text{-ss}}}). 
\end{align*}
We have 
\begin{align*}
    \nu^* K=\Gamma(\mathcal{H}_T(w)^{\mathrm{ss}}, \Gamma_{\mathcal{S}_{\leqslant N'}^{\dag}}(\mathcal{P}_M))
\end{align*}
which vanishes by Proposition~\ref{prop:resol} and Lemma~\ref{lem:vanish2dag}. 
Indeed by Proposition~3.2, $\mathcal{P}_M$ is represented as a filtered colimit of a left
resolution whose terms are finite direct sums of $\mathcal{V}_M$. Since
the local cohomology functor and the global section functor are continuous, Lemma~\ref{lem:vanish2dag} implies the same vanishing for
$\mathcal{P}_M$. 

Therefore by shrinking $T$ if necessary, we have the isomorphism 
\begin{align}\label{PhiTdag1}
\Phi_T(\mathcal{O}_{\mathcal{H}_T(w)^{\mathrm{ss}}})|_{\mathcal{H}_T(\chi_0)^{\text{ss}}} \stackrel{\cong}{\to} 
     \Phi_T^{\varepsilon\dag}(\mathcal{O}_{\mathcal{H}_T(w)^{\varepsilon\dag\text{-ss}}}).
\end{align}
It is enough to show that 
\begin{align}\label{show:dag}
  \Phi_T^{\varepsilon\dag}(\mathcal{O}_{\mathcal{H}_T(w)^{\varepsilon\dag\text{-ss}}}) \in \operatorname{L}(\mathcal{H}_T(\chi_0)^{\mathrm{ss}})_{w'}.   
\end{align}

By our choice of $h_T^{\varepsilon\dag}$, the stack 
$\mathcal{H}_T(w)^{\varepsilon\dag \text{-ss}}$ is a $\mathbb{G}_m$-gerbe over 
a quasi-projective scheme $H_T(w)^{\varepsilon\dag \text{-ss}}$, see (\ref{Gmgerb}). 
We have the equivalence 
\begin{align}\label{equiv:wt0}
\operatorname{Coh}(H_T(w)^{\varepsilon\dag \text{-ss}}) \stackrel{\sim}{\to}
    \operatorname{Coh}(\mathcal{H}_T(w)^{\varepsilon\dag \text{-ss}})_0. 
\end{align}
We identify $\Phi_T^{\varepsilon \dag}$ as a functor through the above equivalence
\begin{align*}
    \Phi_T^{\varepsilon \dag} \colon 
    \operatorname{Coh}(H_T(w)^{\varepsilon\dag\text{-ss}}) \to 
  \operatorname{Coh}(\mathcal{H}_T(\chi_0)^{\mathrm{ss}})_{w'}
\end{align*}
whose kernel object 
\begin{align*}
    \overline{\mathcal{P}}_T^{\varepsilon\dag} \in \operatorname{Coh}(H_T(w)^{\varepsilon\dag\text{-ss}}\times_T \mathcal{H}_T(\chi_0)^{\text{ss}})
\end{align*}
is identified with the weight zero-part 
of the object (\ref{PTvd}) under the equivalence (\ref{equiv:wt0}).  

For any $y\in H_T(w)^{\varepsilon\dag\text{-ss}}$ and the 
corresponding sheaf 
$E_y \in \operatorname{Coh}^{\heartsuit}(\mathcal{C}_t)$, 
we have 
\begin{align}\label{Phi(Oy)}
    \Phi_T^{\varepsilon\dag}(\mathcal{O}_y)=\mathcal{P}_{E_y}|_{\mathcal{H}_T(\chi_0)^{\mathrm{ss}}} \in \operatorname{L}(\mathcal{H}_T(\chi_0)^{\mathrm{ss}})_{w'}
\end{align}
by Corollary~\ref{cor:PE}. 
Let $i_T$ be the closed immersion 
\begin{align*}
    i_T \colon H_T(w)^{\mathrm{ss}}\times_T \mathcal{H}_T(\chi_0) \hookrightarrow 
H_T(w)^{\mathrm{ss}}\times \mathcal{H}_T(\chi_0).
\end{align*}
Since $H_T(w)^{\varepsilon\dag\text{-ss}}$ is a quasi-projective scheme and 
the category $\operatorname{L}(\mathcal{H}_T(\chi_0)^{\mathrm{ss}})$ is a semiorthogonal summand of 
$\operatorname{Coh}(\mathcal{H}_T(\chi_0)^{\mathrm{ss}})$, 
 we have 
\begin{align}\label{PTed}
  i_{T*}  \overline{\mathcal{P}}_T^{\varepsilon\dag} \in \operatorname{Coh}(H_T(w)^{\varepsilon\dag\text{-ss}}) \otimes \operatorname{L}(\mathcal{H}_T(\chi_0)^{\mathrm{ss}})_{w'}. 
\end{align}
Indeed let 
\begin{align*}\mathcal{P}' \in 
\operatorname{Coh}(H_T(w)^{\varepsilon\dag\text{-ss}})\otimes \operatorname{Coh}(\mathcal{H}_T(\chi_0)^{\mathrm{ss}})_{w'}
\end{align*}
be a semiorthogonal factor of $i_{T*}\overline{\mathcal{P}}_T^{\varepsilon\dag}$, 
not contained in the right-hand side in (\ref{PTed}). 
Then the condition \eqref{Phi(Oy)} implies that 
\[
\mathcal{P}'|_{y\times \mathcal{H}_T(\chi_0)^{\mathrm{ss}}}=0
\]
for any $y\in H_T(w)^{\varepsilon\dag\text{-ss}}$. Hence $\mathcal{P}'=0$. 
Therefore (\ref{PTed}) holds
(we also refer to the argument
of~\cite[Lemma~6.2]{PThiggs}). 
Therefore 
the functor $\Phi_T^{\varepsilon\dag}$ 
restricts to the functor 
\begin{align}\label{rest:L}
\Phi_T^{\varepsilon\dag} \colon 
    \operatorname{Coh}(H_T(w)^{\varepsilon\dag\text{-ss}}) \to 
  \operatorname{L}(\mathcal{H}_T(\chi_0)^{\mathrm{ss}})_{w'}. 
\end{align}
In particular the condition (\ref{show:dag}) holds. 
\begin{ssstep}
    The result on Harder--Narasimhan strata.
\end{ssstep}
We next consider Harder--Narasimhan stratification of $\mathcal{H}(\chi_0)$ with respect to the usual stability condition (\ref{ineq:deg}). 
Let 
\begin{align*}
    \mathcal{H}(\chi_0)_{\preceq \mu} \subset \mathcal{H}(\chi_0)
\end{align*}
be an open substack 
consisting of a finite number of Harder--Narasimhan strata 
such that 
\begin{align*}
    \mathcal{S}_{\mu}=\mathcal{H}(\chi_0)_{\preceq \mu}\setminus \mathcal{H}(\chi_0)_{\prec \mu}
\end{align*}
is a Harder--Narasimhan stratum with type $(\mu_1, \ldots, \mu_k)$, see Remark~\ref{rmk:jshrink}. 
We have the following open immersions 
\begin{align*}
j_{\preceq \mu}\colon 
    \mathcal{H}(\chi_0)^{\mathrm{ss}} \stackrel{j_{\prec \mu}}{\hookrightarrow}
\mathcal{H}(\chi_0)_{\prec\mu} \stackrel{j_{\mu}}{\hookrightarrow}
\mathcal{H}(\chi_0)_{\preceq \mu}.
\end{align*}
We consider the functor 
\begin{align}\label{PhiTmu}
    \Phi_{\preceq \mu}:=\Phi|_{\mathcal{H}(\chi_0)_{\preceq \mu}} \colon 
    \operatorname{Coh}(\mathcal{H}(w)^{\mathrm{ss}})_0 \to \operatorname{Coh}(\mathcal{H}(\chi_0)_{\preceq \mu})_{w'}.
\end{align}
Below by induction on $\mu$, we show that 
\begin{align}\label{induct:mu}
\Phi_{\preceq \mu}(\mathcal{O}_{\mathcal{H}(w)^{\mathrm{ss}}})
\in (j_{\preceq \mu})_{!}\operatorname{L}(\mathcal{H}(\chi_0)^{\mathrm{ss}})_{w'}.
\end{align}
The base case of the induction is (\ref{Phi:rest}). 

Suppose by the induction hypothesis that 
\begin{align}\label{induct:mu2}
    \Phi_{\prec \mu}(\mathcal{O}_{\mathcal{H}(w)^{\mathrm{ss}}})
\in (j_{\prec \mu})_{!}\operatorname{L}(\mathcal{H}(\chi_0)^{\mathrm{ss}})_{w'}.
\end{align}
Let $\nu$ be a map 
\begin{align*}
    \nu \colon B\mathbb{G}_m \to \mathcal{H}(\chi_0)_{\preceq \mu}, \ \mathrm{pt} \mapsto 
    M=M_1 \oplus \cdots \oplus M_k
\end{align*}
such that each $M_i$ is semistable
satisfying 
\begin{align}\label{ineq:chir}
r_i=\operatorname{rank}\pi_{*}M_i, \ 
\chi_i=\deg \pi_{*}M_i, \ 
\frac{\chi_i}{r_i}=\mu_i, 
\end{align}
i.e. it is of Harder--Narasimhan type $\mu$. 
We take an \'{e}tale neighborhood $(T, 0)\to (\mathcal{B}, b)$ and an ample $\mathbb{Q}$-divisor $h_T^{\varepsilon\dag}$ as in (\ref{hTeps});
namely it satisfies 
\begin{align}\label{def:hTedag}
    h_T^{\varepsilon \dag}\cdot \mathcal{C}_b^{(a)}=r^{(a)}\left(1+\left(\frac{\chi_i}{r_i}-\frac{\chi}{r}  \right)\varepsilon +\alpha^{(a)}\varepsilon^2   \right)
\end{align}
for $(\alpha^{(a)})_{1\leqslant a\leqslant m}$ as in (\ref{choice:alpha})
satisfying the condition in Lemma~\ref{lem:alphagen}, which only depends on 
the Harder--Narasimhan type (\ref{ineq:chir}). 
The base change of the functor (\ref{PhiTmu}) gives 
\begin{align*}
    \Phi_{T\preceq \mu} \colon \operatorname{Coh}(\mathcal{H}_T(w)^{\mathrm{ss}})_0 \to 
    \operatorname{Coh}(\mathcal{H}_T(\chi_0)_{\preceq \mu})_{w'}.
\end{align*}
Let $\Phi_{T\preceq \mu}^{\varepsilon\dag}$ be the functor 
\begin{align}\label{funct:edag2}
   \Phi_{T\preceq \mu}^{\varepsilon\dag} \colon \operatorname{Coh}(\mathcal{H}_T(w)^{\varepsilon\dag\text{-ss}})_0 \to 
   \operatorname{Coh}(\mathcal{H}_T(\chi_0)_{\preceq \mu})_{w'}
\end{align}
defined by the kernel object 
\begin{align}\label{PTprecmu}
\mathcal{P}_{T\preceq \mu}^{\varepsilon\dag}:=
    \mathcal{P}_T|_{\mathcal{H}_T(w)^{\varepsilon\dag\text{-ss}}\times_T \mathcal{H}_T(\chi_0)_{\preceq \mu}}\in \operatorname{Coh}(\mathcal{H}_T(w)^{\varepsilon\dag\text{-ss}}\times_T \mathcal{H}_T(\chi_0)_{\preceq \mu}).
\end{align}
Then as in the argument proving the isomorphism (\ref{PhiTdag1}), 
by Proposition~\ref{prop:resol} and Lemma~\ref{lem:vanish2dag}, 
the natural map 
\begin{align}\label{nat:isom}
    \Phi_{T \preceq \mu}(\mathcal{O}_{\mathcal{H}_T(w)^{\mathrm{ss}}})\to \Phi_{T\preceq \mu}^{\varepsilon\dag}(\mathcal{O}_{\mathcal{H}_T(w)^{\varepsilon\dag\text{-ss}}})
\end{align}
is an isomorphism (after shrinking $T$ if necessary). 


Below we show that 
\begin{align}\label{ets:mu}
     \Phi_{T\preceq \mu}^{\varepsilon\dag}(\mathcal{O}_{\mathcal{H}_T(w)^{\varepsilon\dag\text{-ss}}})\in 
     (j_{T\mu})_{!}\operatorname{L}(\mathcal{H}_T(\chi_0)_{\prec \mu})_{w'}
     \subset \operatorname{L}(\mathcal{H}_T(\chi_0)_{\preceq \mu})_{w'}.
\end{align}
In fact as (\ref{nat:isom}) is an isomorphism, the condition (\ref{ets:mu}) together with 
the induction hypothesis (\ref{induct:mu2}) implies 
(\ref{induct:mu}), see Remark~\ref{rmk:jshrink}. 

As in (\ref{Gmgerb}), the stack $\mathcal{H}_T(w)^{\varepsilon\dag\text{-ss}}$ is a $\mathbb{G}_m$-gerbe over 
$H_T(w)^{\varepsilon\dag\text{-ss}}$, and the functor (\ref{funct:edag2}) is identified with 
\begin{align}\label{funct:edag3}
   \Phi_{T\preceq \mu}^{\varepsilon\dag} \colon \operatorname{Coh}(H_T(w)^{\varepsilon\dag\text{-ss}}) \to 
   \operatorname{Coh}(\mathcal{H}_T(\chi_0)_{\preceq \mu})_{w'}
\end{align}
with kernel object 
\begin{align*}
    \overline{\mathcal{P}}_{T\preceq \mu}^{\varepsilon\dag} \in \operatorname{Coh}(H_T(w)^{\varepsilon\dag\text{-ss}}\times_T \mathcal{H}_T(\chi_0)_{\preceq \mu})
\end{align*}
the weight zero part of (\ref{PTprecmu}) for the factor 
$\mathcal{H}_T(w)^{\varepsilon\dag\text{-ss}}$.
For $y\in H_T(w)^{\varepsilon\dag\text{-ss}}$, let $E_y\in \operatorname{Coh}^{\heartsuit}(\mathcal{C}_t)$ be the corresponding sheaf. 
Then we have 
\begin{align*}
     \Phi_{T\preceq \mu}^{\varepsilon\dag}(\mathcal{O}_y)=\mathcal{P}_{E_y}|_{\mathcal{H}_T(\chi_0)_{\preceq \mu}} \in \operatorname{L}(\mathcal{H}_T(\chi_0)_{\preceq \mu})_{w'}
\end{align*}
by Corollary~\ref{cor:PE}.

Moreover, suppose that $(\nu_1, \ldots, \nu_k)$ 
are the $\mathbb{G}_m$-weights of $M$, and suppose that they satisfy $\nu_1>\cdots>\nu_k$. Then by Lemma~\ref{lem:lower},  
the lower bound of the condition 
\begin{align*}
    \mathrm{wt}(\iota_{*}\nu_{\circ}^{\mathrm{reg}*}\mathcal{P}_{E_y}) \subset\left[\frac{1}{2}c_1(\nu^* \mathbb{L}_{\mathcal{H}_T}^{<0}), \frac{1}{2}c_1(\nu^* \mathbb{L}_{\mathcal{H}_T}^{>0})  \right]+c_1(\nu^* \delta_{w'})
\end{align*}
can be achieved only if there is an exact sequence 
\begin{align*}
    0\to E_y'' \to E_y \to E_y' \to 0
\end{align*}
such that $E_y''$ is supported on $C_{I_i^{\circ}}$ and $E_y'$ is supported on $C_{I_i}$, and 
\begin{align*}
    \frac{\deg (\pi_{*}E_{y}'')}{\operatorname{rank} (\pi_{*}E_y'')}= \frac{\deg (\pi_{*}E_{y}')}{\operatorname{rank} (\pi_{*}E_y')}.
\end{align*}
Here $C_i=\mathrm{Supp}(M_i)$ and $I_i=\{1, \ldots, i\}$. 
This implies that 
\begin{align*}
     \frac{\deg (\pi_{*}E_{y}'')}{h_T^{\varepsilon\dag}(C_{I_i^{\circ}})}> \frac{\deg (\pi_{*}E_{y}')}{h_T^{\varepsilon\dag}(C_{I_i})}
\end{align*}
by the inequalities $\mu_1>\cdots>\mu_k$ and the definition of $h_T^{\varepsilon\dag}$ in (\ref{def:hTedag}). 
The above inequality contradicts that $E_y$ is $h_T^{\varepsilon\dag}$-semistable,
therefore we have 
\begin{align*}
    \mathrm{wt}(\iota_{*}\nu_{\circ}^{\mathrm{reg}*}\mathcal{P}_{E_y}) \subset\left(\frac{1}{2}c_1(\nu^* \mathbb{L}_{\mathcal{H}_T}^{<0}), \frac{1}{2}c_1(\nu^* \mathbb{L}_{\mathcal{H}_T}^{>0})  \right]+c_1(\nu^* \delta_{w'})
\end{align*}
when $\nu_1>\cdots>\nu_k$. 

This implies that (see Remarks~\ref{rmk:HN!} and~\ref{rmk:T})
\begin{align*}
      \Phi_{T\preceq \mu}^{\varepsilon\dag}(\mathcal{O}_y)=\mathcal{P}_{E_y}
      \in  (j_{T\mu})_{!}\operatorname{L}(\mathcal{H}_T(\chi_0)_{\prec \mu})_{w'}.
\end{align*}
Then by the same argument proving (\ref{PTed}), we have 
\begin{align*}
    (i_{T\preceq \mu})_{*}\overline{\mathcal{P}}_{T\preceq \mu}^{\varepsilon\dag} \in 
    \operatorname{Coh}(H_T(w)^{\varepsilon\dag\text{-ss}})\otimes (j_{T_{\mu}})_{!}\operatorname{L}(\mathcal{H}_T(\chi_0)_{\prec \mu})_{w'}.
\end{align*}
Here $i_{T\preceq \mu}$ is the closed immersion 
\begin{align*}
  i_{T\preceq \mu} \colon     H_T(w)^{\varepsilon\dag\text{-ss}}\times_T \mathcal{H}_T(\chi_0)_{\preceq \mu} \hookrightarrow 
H_T(w)^{\varepsilon\dag\text{-ss}}\times \mathcal{H}_T(\chi_0)_{\preceq \mu}.
\end{align*}
Therefore as in (\ref{rest:L}), 
the functor (\ref{funct:edag3})
restricts to the functor 
\begin{align*}
       \Phi_{T\preceq \mu}^{\varepsilon\dag} \colon \operatorname{Coh}(H_T(w)^{\varepsilon\dag\text{-ss}}) \to 
  (j_{T\mu})_{!} \operatorname{L}(\mathcal{H}_T(\chi_0)_{\prec \mu})_{w'}.
   \end{align*}
   In particular 
the condition (\ref{ets:mu}) holds.

\label{thm:whit}
For $\mathcal{B}=\mathcal{B}^A$, there 
is an isomorphism in $\operatorname{L}_{\mathcal{N}}(\mathcal{H}(\chi_0))_{w'}$
\begin{align*}
    \Phi(\mathcal{O}_{\mathcal{H}(w)^{\mathrm{ss}}})
    \cong s_{!}\mathcal{O}_{\mathcal{B}}.
\end{align*}

Recall the factorization of $s$ in Lemma~\ref{lem:factori}
\begin{align*}
s \colon \mathcal{B}
\stackrel{\overline{s}}{\to}
\mathcal{H}(\chi_0)^{\mathrm{ss}}
\stackrel{j}{\hookrightarrow}
\mathcal{H}(\chi_0).
\end{align*}
Then by Lemma~\ref{lem:ids}, we have the isomorphism 
\begin{align*}
    \overline{s}^*(\Phi(\mathcal{O}_{\mathcal{H}(w)^{\mathrm{ss}}})|_{\mathcal{H}(\chi_0)^{\mathrm{ss}}})\cong h_{*}\mathcal{O}_{\mathcal{H}(w)^{\mathrm{ss}}}
\end{align*}
where $h \colon \mathcal{H}(w)^{\mathrm{ss}} \to \mathcal{B}$ is the Hitchin map. 
By the adjunction of the natural map $\mathcal{O}_{\mathcal{B}} \to h_{*}\mathcal{O}_{\mathcal{H}(w)^{\mathrm{ss}}}$, 
there is a natural morphism
\begin{align}\label{map:sdag}
    \overline{s}_{!}\mathcal{O}_{\mathcal{B}}
    \to
    \Phi(\mathcal{O}_{\mathcal{H}(w)^{\mathrm{ss}}})
    |_{\mathcal{H}(\chi_0)^{\mathrm{ss}}}.
\end{align}
Here $\overline{s}_!$ is given by the formula (\ref{formula:sbar}).  
By Theorem~\ref{thm:PhiO}, it is enough to show that the above map is an isomorphism.

Let $(T, 0) \to (\mathcal{B}, b)$ be an \'{e}tale map as in Step~1 of Theorem~\ref{thm:PhiO}, 
and take a perturbation 
$h_T^{\varepsilon\dag}$ of $h_T$ as in Subsection~\ref{subsec:stO};
namely it satisfies 
\begin{align}\label{h:generic}
    h_T^{\varepsilon\dag} \cdot \mathcal{C}_b^{(a)}=r^{(a)}(1+\alpha^{(a)}\varepsilon^2)
\end{align}
for $(\alpha^{(a)})_{1\leqslant a\leqslant m}$ as in (\ref{choice:alpha}) satisfying 
the condition in Lemma~\ref{lem:alphagen}.

Let $\Phi_T^{\varepsilon\dag}$ be the functor
\begin{align}\label{PhiTe}
\Phi_T^{\varepsilon\dag} \colon
\operatorname{Coh}(\mathcal{H}_T(w)^{\varepsilon\dag\text{-ss}})_0
\to
\operatorname{Coh}(\mathcal{H}_T(\chi_0)^{\varepsilon\dag\text{-ss}})_{w'}
\end{align}
defined by the kernel object
\begin{align*}
    \mathcal{P}_T^{\varepsilon\dag\dag}
    :=
    \mathcal{P}_T
    |_{\mathcal{H}_T(w)^{\varepsilon\dag\text{-ss}}
    \times_T
    \mathcal{H}_T(\chi_0)^{\varepsilon\dag\text{-ss}}}
    \in
    \operatorname{Coh}(
    \mathcal{H}_T(w)^{\varepsilon\dag\text{-ss}}
    \times_T
    \mathcal{H}_T(\chi_0)^{\varepsilon\dag\text{-ss}}
    ).
\end{align*}
By the genericity of $h_T^{\varepsilon\dag}$ (i.e.\ semistability is equivalent to stability as in (\ref{ss=st})), 
by Theorem~\ref{thm:MRV} 
the functor \eqref{PhiTe} is an equivalence 
with inverse given by (after shrinking $T$ if necessary, see Remark~\ref{rmk:dualizing})
\begin{align}\label{kernel:inv2}
(\mathcal{P}_T^{\varepsilon\dag\dag})^{\vee}[p_a]
\in
\operatorname{Coh}(
\mathcal{H}_T(w)^{\varepsilon\dag\text{-ss}}
\times_T
\mathcal{H}_T(\chi_0)^{\varepsilon\dag\text{-ss}}
).
\end{align}
Here $p_a$ is the arithmetic genus of the spectral curve (\ref{def:pa}). 

We denote by
$\overline{s}_T \colon T \to \mathcal{H}_T(\chi_0)^{\mathrm{ss}}$
the base change of $\overline{s}$.
It factors through the map $\overline{s}_T^{\varepsilon\dag}$:
\begin{align*}
    \overline{s}_T \colon
    T
    \stackrel{\overline{s}_T^{\varepsilon\dag}}{\to}
    \mathcal{H}_T(\chi_0)^{\varepsilon\dag\text{-ss}}
    \hookrightarrow
    \mathcal{H}_T(\chi_0)^{\mathrm{ss}}.
\end{align*}
The composition 
\begin{align}\label{compose:vd}
T\stackrel{\overline{s}_T^{\varepsilon\dag}}{\to} \mathcal{H}_T(\chi_0)^{\varepsilon\dag\text{-ss}} \to H_T(\chi_0)^{\varepsilon\dag\text{-ss}} 
\end{align}
is a closed immersion since it is a section of the projective morphism 
$H_T(\chi_0)^{\varepsilon\dag\text{-ss}}  \to T$, given by the universality of the good moduli space morphism. Since the second map in (\ref{compose:vd}) is a $\mathbb{G}_m$-gerbe by the genericity of $h_T^{\varepsilon\dag}$, similarly to Lemma~\ref{lem:factori}
we have the isomorphism
\begin{align}\label{isom:vd}
    (\overline{s}_{T}^{\varepsilon\dag})_{!}\cong ((\overline{s}_{T}^{\varepsilon\dag})_{*})_{w'}[-p_a]
\end{align}
as functors 
\begin{align*}
    \operatorname{Coh}(T) \to \operatorname{L}(\mathcal{H}_T(\chi_0)^{\varepsilon\dag\text{-ss}})_{w'} =
    \operatorname{Coh}(\mathcal{H}_T(\chi_0)^{\varepsilon\dag\text{-ss}})_{w'}.
\end{align*}
On the other hand, by Lemma~\ref{lem:ids} we have 
\begin{align}\label{isom:vd2}
    (\operatorname{id} \times \overline{s}_T^{\varepsilon\dag})^* \mathcal{P}_T^{\varepsilon\dag\dag}\cong 
    \mathcal{O}_{\mathcal{H}_T(w)^{\varepsilon\dag\text{-ss}}}.
\end{align}
Therefore (\ref{isom:vd}), (\ref{isom:vd2}) together with the description of the kernel object (\ref{kernel:inv2})
of $(\Phi_T^{\varepsilon\dag})^{-1}$
show the isomorphism in $\operatorname{Coh}(\mathcal{H}_T(w)^{\varepsilon\dag\text{-ss}})_0$
\begin{align*}
 (\Phi_T^{\varepsilon\dag})^{-1}
 \bigl(
 (\overline{s}_T^{\varepsilon\dag})_{!}\mathcal{O}_T
 \bigr)
 \cong
 \mathcal{O}_{\mathcal{H}_T(w)^{\varepsilon\dag\text{-ss}}}.
\end{align*}
As $\Phi_T^{\varepsilon\dag}$ is an equivalence, we conclude the isomorphism 
in $\operatorname{Coh}(\mathcal{H}_T(\chi_0)^{\varepsilon\dag\text{-ss}})_{w'}$
\begin{align*}
    \Phi_T^{\varepsilon\dag}
    (\mathcal{O}_{\mathcal{H}_T(w)^{\varepsilon\dag\text{-ss}}})
    \cong
    (\overline{s}_T^{\varepsilon\dag})_{!}\mathcal{O}_T.
\end{align*}

An argument proving the isomorphism \eqref{PhiTdag1} also shows an isomorphism
\begin{align*}
\Phi_T(\mathcal{O}_{\mathcal{H}_T(w)^{\mathrm{ss}}})
|_{\mathcal{H}_T(\chi_0)^{\varepsilon\dag\text{-ss}}}
\stackrel{\cong}{\to}
\Phi_T^{\varepsilon\dag}
(\mathcal{O}_{\mathcal{H}_T(w)^{\varepsilon\dag\text{-ss}}}).
\end{align*}
It follows that the natural map
\begin{align}\label{sT:natural}
    (\overline{s}_T)_{!}\mathcal{O}_T
    \to
    \Phi_T(\mathcal{O}_{\mathcal{H}_T(w)^{\mathrm{ss}}})
\end{align}
is an isomorphism on the open substack
\begin{align*}
   \widetilde{\mathcal{H}}_T(\chi_0)^{\mathrm{ss}} :=
    \bigcup_{h_T^{\varepsilon\dag}}
    \mathcal{H}_T(\chi_0)^{\varepsilon\dag\text{-ss}}
    \subset
    \mathcal{H}_T(\chi_0)^{\mathrm{ss}}.
\end{align*}
Here the union is taken over the $h_T^{\varepsilon\dag}$-semistable loci
for all perturbations $h_T^{\varepsilon\dag}$ as in (\ref{h:generic}), satisfying the condition of Lemma~\ref{lem:alphagen}.
Its complement $\mathcal{Z}$ is a closed substack which is disjoint
from the closed substack $\overline{s}_T(T)$. Therefore, we have the 
distinguished triangle
\begin{align*}
R \to  (\overline{s}_T)_{!}\mathcal{O}_T \to 
    \Phi_T(\mathcal{O}_{\mathcal{H}_T(w)^{\mathrm{ss}}})
\end{align*}
where $R$ is supported on the complement of $\widetilde{\mathcal{H}}_T(\chi_0)^{\mathrm{ss}}$. 
By Lemma~\ref{lem:consv} below, we have $R=0$, hence
\eqref{sT:natural} is an isomorphism.
Since this holds in an \'{e}tale neighborhood of any $b \in \mathcal{B}$,
the map \eqref{map:sdag} is an isomorphism.

   Suppose that there is a non-zero object
\[
A \in \operatorname{L}(\mathcal{H}_T(\chi_0)^{\mathrm{ss}})_{w'}
\]
satisfying $A|_{\widetilde{\mathcal{H}}_T(\chi_0)^{\mathrm{ss}}}=0$.
Let $h_{T}^{\varepsilon\dag}$ be taken as in \eqref{h:generic} for
$(\alpha^{(a)})_{1\leqslant a\leqslant m}$ satisfying the condition in
Lemma~\ref{lem:alphagen}. Let
    \begin{align*}
        \mathcal{H}_T(\chi_0)^{\mathrm{ss}}=\mathcal{H}_T(\chi_0)^{\varepsilon\dag\text{-ss}}\sqcup \mathcal{S}_1^{\dag} \sqcup \cdots \sqcup \mathcal{S}_{N}^{\dag} 
    \end{align*}
    the Harder--Narasimhan stratification with respect to $h_T^{\varepsilon\dag}$, such that 
\begin{align*}
       \mathcal{H}_T(\chi_0)^{\mathrm{ss}}_{\preceq i}= \mathcal{H}_T(\chi_0)^{\varepsilon\dag\text{-ss}}\sqcup \mathcal{S}_1^{\dag} \sqcup \cdots \sqcup \mathcal{S}_{i}^{\dag} 
\end{align*}
 is open in $\mathcal{H}_T(\chi_0)^{\mathrm{ss}}$.    
 Then as $A|_{\mathcal{H}_T(\chi_0)^{\varepsilon\dag\text{-ss}}}=0$, there is $i$ such that 
 \begin{align}\label{A:vanish}
     A|_{\mathcal{H}_T(\chi_0)_{\prec i}^{\mathrm{ss}}}=0, \ A|_{\mathcal{H}_T(\chi_0)_{\preceq i}^{\mathrm{ss}}}\neq 0.
 \end{align}

 Since $\mathcal{S}_i^{\dag}$ is a $\Theta$-stratum of $\mathcal{H}_T(\chi_0)_{\preceq i}$, 
 the same argument of~\cite[Proposition~8.23]{PTlim} shows that we have the 
 semiorthogonal decomposition 
 \begin{align*}
     \operatorname{L}(\mathcal{H}_T(\chi_0)_{\preceq i}^{\mathrm{ss}})=\langle \operatorname{L}(\mathcal{Z}_i^{\dag})_{\delta_{w'}}, (j_i)_{!}\operatorname{L}(\mathcal{H}_T(\chi_0)^{\mathrm{ss}}_{\prec i})_{w'} \rangle.
 \end{align*}
 Here $j_i$ is the open immersion 
 \begin{align*}
     j_i \colon \mathcal{H}_T(\chi_0)^{\mathrm{ss}}_{\prec i} \hookrightarrow \mathcal{H}_T(\chi_0)^{\mathrm{ss}}_{\preceq i}
 \end{align*}
 and $\mathcal{S}_i^{\dag} \to \mathcal{Z}_i^{\dag}$ is the center of the $\Theta$-stratum $\mathcal{S}_i^{\dag}$. 
 The first summand is given by 
$\tau_{i*}f_i^*$ for the diagram 
\begin{align*}
        \mathcal{Z}_i^{\dag} \stackrel{f_i}{\leftarrow} \mathcal{S}_i^{\dag} \stackrel{\tau_i}{\hookrightarrow} \mathcal{H}_T(\chi_0)_{\preceq i}^{\mathrm{ss}}.
    \end{align*}
 Then from (\ref{A:vanish}), we have 
 \begin{align*}
     A|_{\mathcal{H}_T(\chi_0)_{\preceq i}^{\mathrm{ss}}}\cong 
     \tau_{i*}f_i^* B_i
 \end{align*}
 for some non-zero $B_i \in \operatorname{L}(\mathcal{Z}_i^{\dag})_{\delta_{w'}}$. 

    By Lemma~\ref{lemma:nonempty} below, for each $z\in \mathcal{Z}_i^{\dag}$, there is another $h_T^{\varepsilon'\dag}$ determined by generic $(\alpha^{'(a)})_{1\leqslant a\leqslant m}$
   and $z' \in \mathcal{S}_i^{\dag} \cap \mathcal{H}_T(\chi_0)^{\varepsilon'\dag\text{-ss}}$ which maps to $z$
   under the natural map $\mathcal{S}_i^{\dag} \to \mathcal{Z}_i^{\dag}$. 
   Therefore by taking $z$ to be a point in the support of $B_i$, we conclude 
   $A|_{\mathcal{H}_T(\chi_0)^{\varepsilon'\dag\text{-ss}}}\neq 0$, 
   which contradicts the assumption that $A|_{\widetilde{\mathcal{H}}_T(\chi_0)^{\mathrm{ss}}}=0$.

For a rank-one torsion-free sheaf $E \in \operatorname{Coh}^{\heartsuit}(\mathcal{C}_b)$, recall from 
Lemma~\ref{lem:Qp} that there is an exact sequence 
\begin{align*}
    0\to \mathcal{L} \to E \to 
    \bigoplus_{p \in \mathrm{Sing}(\mathcal{C}_b)}\mathcal{O}_{W_p} \to 0
\end{align*}
where $\mathcal{L}$ is a line bundle and $W_p \hookrightarrow Z_p$ is a possibly empty closed subscheme
with length $0\leqslant n_p \leqslant m_p/2$. We set $n_p':=m_p'-n_p$,
where $m_p'$ is the round-down of $m_p/2$. Note that $n_p'=0$ if and only if 
$E|_{\widehat{\mathcal{C}}_{b, p}}$ is obtained as a push-forward from its normalization. 

A point $z\in \mathcal{Z}_i^{\dag}$ corresponds to a direct sum
\begin{align*}
    A_1 \oplus \cdots \oplus A_{\ell} \in \operatorname{Coh}^{\heartsuit}(\mathcal{C}_b)
\end{align*}
for $\ell\geqslant 2$ such that each $A_{\alpha}$ is
$h_T^{\varepsilon\dag}$-semistable with 
\begin{align*}
    \mu^{\varepsilon \dag}(A_1)>\cdots>\mu^{\varepsilon \dag}(A_{\ell}), \ 
    \mu^0(A_1)=\cdots=\mu^0(A_{\ell}).
\end{align*}
Let $D_{\alpha}:=\mathrm{Supp}(A_{\alpha})$. 
Note that each $A_{\alpha}$ is a line bundle on $D_{\alpha}$ at 
$D_{\alpha} \cap D_{\beta}$ for $\beta\neq \alpha$, as $D_{\alpha}$ is smooth at 
$D_{\alpha} \cap D_{\beta}$. 
We then take $E\in \operatorname{Coh}^{\heartsuit}(\mathcal{C}_b)$ with $h_T^{\varepsilon\dag}$-HN filtration, using Lemma~\ref{lem:line} below,
\begin{align*}
    E_1 \subset E_2 \subset \cdots \subset E_{\ell}=E
\end{align*}
such that $E_{\alpha}/E_{\alpha-1}\cong A_{\alpha}$ and $E$ is a line bundle at any 
$p \in D_{\alpha} \cap D_{\beta}$ 
for $1\leqslant \alpha<\beta \leqslant \ell$; this is possible since each $A_{\alpha}$ is a line bundle at any 
$p\in D_{\alpha} \cap D_{\beta}$ 
for $\beta\neq \alpha$ by the definition of type $A$ singularities of $\mathcal{C}_b$. 
Note that $E$ corresponds to a $k$-valued point of $\mathcal{S}_i^{\dag}$ and 
satisfies $\deg \pi_{*}E=\chi_0$. 

Below we show that $E$ is stable with respect to 
$h_T^{\varepsilon'\dag}$ determined by generic $(\alpha^{'(a)})_{1\leqslant a\leqslant m}$ as in Lemma~\ref{lem:alphagen}. 
Let 
\begin{align*}
    \mathcal{C}_b=\mathcal{C}_b^{(1)} \cup \cdots \cup \mathcal{C}_b^{(m)}, \quad 
    r^{(a)}=\operatorname{rank}(\pi_{*}\mathcal{O}_{\mathcal{C}_b^{(a)}})
\end{align*}
be the decomposition into irreducible components. 
For a subset $K\subset \{1, \ldots, m\}$, we write 
\[
\mathcal{C}_b^{(K)}=\bigcup_{a\in K} \mathcal{C}_b^{(a)}, 
\qquad 
K^{\circ}:=\{1,\ldots,m\}\setminus K.
\]
By our choice of the extensions, \(E\) is locally free at
the intersection points between components belonging to different HN factors;
equivalently the gluing length \(n'_p\) is positive at such points. 
Since \(\ell\geqslant 2\), any non-empty proper subset \(K\subset \{1, \ldots, m\}\) separates two irreducible
components belonging to different HN factors. As any two distinct irreducible
components of \(\mathcal{C}_b\) meet for \(g\geqslant 2\), the intersection
\(\mathcal{C}_b^{(K)}\cap \mathcal{C}_b^{(K^{\circ})}\) contains a point at which \(E\) is locally free by
construction. Thus
\begin{align}\label{sum:positive}
\sum_{p\in \mathcal{C}_b^{(K)}\cap \mathcal{C}_b^{(K^{\circ})}} n'_p>0.
\end{align}

We then set 
\begin{align*}
    \chi^{(a)}:=\deg \pi_{*}(E|_{\mathcal{C}_b^{(a)}}^{\mathrm{free}}) \in \mathbb{Z}. 
\end{align*}
Here $E|_{\mathcal{C}_b^{(a)}}^{\mathrm{free}}$ is the torsion-free quotient of $E|_{\mathcal{C}_b^{(a)}}$. 
Let $r^{(K)}:=\sum_{a\in K}r^{(a)}$. 
Then we have 
\begin{align*}
    \deg \pi_{*}(E|_{\mathcal{C}_b^{(K)}}^{\mathrm{free}})
    =
    \sum_{a\in K} \chi^{(a)} 
    -\sum_{\substack{a,a' \in K\\ a<a'}}
    \sum_{p\in \mathcal{C}_b^{(a)} \cap \mathcal{C}_b^{(a')}}n_p'.
\end{align*}
By the exact sequence 
\begin{align*}
    0\to E' \to E \to E|_{\mathcal{C}_b^{(K)}}^{\mathrm{free}} \to 0
\end{align*}
we have, by the semistability of $E$,
\begin{align}\label{ineq:chi}
    \frac{\chi_0}{r} \leqslant 
    \frac{1}{r^{(K)}}\left(
    \sum_{a\in K} \chi^{(a)} 
    -\sum_{\substack{a,a' \in K\\ a<a'}}
    \sum_{p\in \mathcal{C}_b^{(a)} \cap \mathcal{C}_b^{(a')}}n_p'  
    \right).
\end{align}
By the exact sequence 
\begin{align*}
    0\to E'' \to E \to (E|_{\mathcal{C}_b^{(K^\circ)}})^{\mathrm{free}} \to 0
\end{align*}
and noting that 
\begin{align}\notag
    \deg \pi_{*}E''
    =
    \deg \pi_{*}(E|_{\mathcal{C}_b^{(K)}}^{\mathrm{free}})
    -\sum_{p\in \mathcal{C}_b^{(K)} \cap \mathcal{C}_b^{(K^{\circ})}}n_p',
\end{align}
we obtain the inequality 
\begin{align}\label{ineq:chi2}
   \frac{1}{r^{(K)}}\left(
   \sum_{a\in K} \chi^{(a)} 
   -\sum_{\substack{a,a' \in K\\ a<a'}}
   \sum_{p\in \mathcal{C}_b^{(a)} \cap \mathcal{C}_b^{(a')}}n_p'  
   \right)
   -\frac{1}{r^{(K)}}\sum_{p\in \mathcal{C}_b^{(K)} \cap \mathcal{C}_b^{(K^{\circ})}}n_p'
   \leqslant \frac{\chi_0}{r}.
\end{align}

Moreover, by $\deg \pi_{*}E=\chi_0$, we have 
\begin{align}\label{equal:chi}
    \sum_{a=1}^m \chi^{(a)}
    -\sum_{a<a'}\sum_{p\in \mathcal{C}_b^{(a)} \cap \mathcal{C}_b^{(a')}}n_p'
    =\chi_0.
\end{align}
By setting 
\begin{align*}
    \widetilde{\chi}^{(a)}
    =
    \chi^{(a)}-\frac{r^{(a)}}{r}\cdot \chi_0,
\end{align*}
the inequalities (\ref{ineq:chi}), (\ref{ineq:chi2}) imply 
\begin{align}\label{ineq:chi4}
    0
    \leqslant 
    \sum_{a\in K}\widetilde{\chi}^{(a)}
    -\sum_{\substack{a,a' \in K\\ a<a'}}
    \sum_{p\in \mathcal{C}_b^{(a)}\cap \mathcal{C}_b^{(a')}}n_p'
    \leqslant 
    \sum_{p\in \mathcal{C}_b^{(K)} \cap \mathcal{C}_b^{(K^{\circ})}}n_p', 
\end{align}
and the equality (\ref{equal:chi}) implies 
\begin{align}\label{cond:chitilde}
    \sum_{a=1}^m \widetilde{\chi}^{(a)}
    =
    \sum_{a<a'}\sum_{p\in \mathcal{C}_b^{(a)} \cap \mathcal{C}_b^{(a')}}n_p'.
\end{align}

Let $\nabla \subset \mathbb{R}^m$ be the subset satisfying the above conditions for
$(\widetilde{\chi}^{(1)}, \ldots, \widetilde{\chi}^{(m)})$. Then it is an $(m-1)$-dimensional 
polytope by the conditions (\ref{sum:positive}), (\ref{cond:chitilde}). Indeed it contains 
the interior point $(t^{(1)}, \ldots, t^{(m)}) \in \nabla$ by setting 
\begin{align*}
    t^{(a)}=\frac{1}{2}\sum_{a'\neq a}
    \sum_{p\in \mathcal{C}_b^{(a)} \cap \mathcal{C}_b^{(a')}} n_p',
\end{align*}
where the inequalities in (\ref{ineq:chi4}) are strict by replacing $\widetilde{\chi}^{(a)}$ with $t^{(a)}$. 

Suppose that $(\widetilde{\chi}^{(1)}, \ldots, \widetilde{\chi}^{(m)})$ lies in the boundary of $\nabla$. Then by a small perturbation 
\begin{align*}
r^{(a)} \mapsto r^{(a)}(1+\varepsilon^{(a)}), \quad
\lvert \varepsilon^{(a)} \rvert \ll 1, \quad
\sum_{a=1}^m r^{(a)}\varepsilon^{(a)}=0,
\end{align*}
the point $(\widetilde{\chi}^{(1)}, \ldots, \widetilde{\chi}^{(m)})$ changes as  
\begin{align}\label{change:chi}
 (\widetilde{\chi}^{(1)}, \ldots, \widetilde{\chi}^{(m)}) \mapsto   
 \left(\widetilde{\chi}^{(1)}-\frac{r^{(1)} \varepsilon^{(1)}}{r}\chi_0, \ldots,
 \widetilde{\chi}^{(m)}-\frac{r^{(m)} \varepsilon^{(m)}}{r}\chi_0\right).
\end{align}
A choice of $(\varepsilon^{(1)}, \ldots, \varepsilon^{(m)})$ is $(m-1)$-dimensional.
Therefore for a generic choice of $(\alpha^{'(a)})_{1\leqslant a\leqslant m}$ 
satisfying the condition of Lemma~\ref{lem:alphagen}, by setting
$\varepsilon^{(a)}=\alpha^{'(a)} \cdot \varepsilon^2$ for $\lvert \varepsilon \rvert \ll 1$, 
the right-hand side of (\ref{change:chi}) 
lies in the interior of $\nabla$.
This means that for a perturbation $h_T^{\varepsilon'\dag}$ of $h_T$ 
with $h_T^{\varepsilon'\dag} \cdot \mathcal{C}_b^{(a)}=r^{(a)}(1+\alpha^{'(a)}\varepsilon^2)$, the sheaf $E$ is $h_T^{\varepsilon'\dag}$-stable.

\label{lem:line}
Let $\mathcal{C}$ be a reduced planar curve, and $\mathcal{C}=C_1 \cup C_2$
where $C_i$ are unions of irreducible components. 
Let $E_i \in \operatorname{Coh}^{\heartsuit}(C_i)$ be rank-one torsion-free 
sheaves which are line bundles on $C_i$ at $C_1 \cap C_2$. Then 
there is an exact sequence in $\operatorname{Coh}^{\heartsuit}(\mathcal{C})$
\begin{align*}
    0\to E_1 \to E \to E_2 \to 0
\end{align*}
such that $E$ is a line bundle on $\mathcal{C}$ at $C_1 \cap C_2$.

For $G\in \{\operatorname{SL}_r, \operatorname{PGL}_r\}$, the Hitchin base $\mathrm{B}_G$ is given by 
\begin{align*}
    \mathrm{B}_{G}=\bigoplus_{i=2}^r \Gamma(\Omega_C^i) \hookrightarrow 
    \mathrm{B}_{\operatorname{GL}_r}=\bigoplus_{i=1}^r \Gamma(\Omega_C^i)
\end{align*}
such that the $H^0(\Omega_C)$-action (\ref{act:gamma}) gives the isomorphism 
\begin{align}\label{act:isom}
    \mathrm{B}_{G}\times H^0(\Omega_C) \stackrel{\cong}{\to} \mathrm{B}_{\operatorname{GL}_r}^{\mathrm{cl}}.
\end{align}

Let $\mathrm{Pic}(C)=\mathrm{Bun}_{\mathbb{G}_m}$ and 
consider the map 
\begin{align*}
\det \colon 
    \mathrm{Higgs}_{\operatorname{GL}_r}^{\operatorname{\mathrm{tr}}=0} \to \operatorname{Pic}(C), \ (F, \theta)\mapsto \det F.
\end{align*}

\label{rmk:Acirc}
Later we will consider $\mathcal{B}=\mathcal{B}^A$. It is of the form 
\begin{align}\label{BAcirc}
\mathcal{B}_{\circ}^A \times H^0(\Omega_C) \stackrel{\cong}{\to} \mathcal{B}^A
\end{align}
for an open subset $\mathcal{B}_{\circ}^A \subset \mathcal{B}_{\circ}$ under the isomorphism (\ref{act:isom}), 
    since the type $A$-locus $\mathcal{B}^A$ is unchanged by the action of $H^0(\Omega_C)$.

We define $\mathcal{H}_{\mathrm{S}}(w_0)$ by the Cartesian square 
\begin{align*}
    \xymatrix{
\mathcal{H}_{\mathrm{S}}(w_0) \ar[r]^-{i} \ar[d] \ar@{}[rd]|\square & \mathcal{H}_{\circ}(w_0) \ar[d]^-{\mathrm{Nm}} \\
\mathrm{pt} \ar[r] & \operatorname{Pic}^0(C).

\label{rmk:perfSP}
If $\mathcal{B}_{\circ} \subset \mathrm{B}_{G}^{\mathrm{red}}:=\mathrm{B}_{\operatorname{GL}_r}^{\mathrm{red}} \cap \mathrm{B}_{G}$, 
then similarly to Remark~\ref{rmk:nilp} we have 
\begin{align*}
    \operatorname{Coh}_{\mathcal{N}}(\mathcal{H}_{\mathrm{S}}(w_0))=\mathrm{Perf}(\mathcal{H}_{\mathrm{S}}(w_0)), \ 
    \operatorname{Coh}_{\mathcal{N}}(\mathcal{H}_{\mathrm{P}})=\mathrm{Perf}(\mathcal{H}_{\mathrm{P}}).
\end{align*}
   Indeed the automorphism groups of $\mathcal{H}_{\mathrm{S}}(w_0)$, $\mathcal{H}_{\mathrm{P}}$ are 
   subgroups (or quotients) of tori, hence abelian. Therefore the nilpotent cone is the 
   zero section, as in Remark~\ref{rmk:nilp}.

\label{lbundle:pull}
    There is a natural isomorphism 
    \begin{align*}
        \alpha^* \mathcal{P}_{\circ} \cong p_{12}^* \mathcal{P}_{\circ} \otimes p_{13}^* \mathcal{L}.
    \end{align*}

The natural transform (\ref{nat:trans}) is defined 
by the adjunction and the commutative diagram (\ref{commute:Phi})
\begin{align*}
    \Phi \Rightarrow \Phi \circ i_{*} \circ i^* \cong p^* \circ \Phi_{\mathrm{S}/\mathrm{P}} \circ i^*. 
\end{align*}

  We consider the map 
\begin{align}\label{idp*}
(\operatorname{id} \times p)^* \gamma \colon 
(\operatorname{id} \times p)^* (\operatorname{id} \times p)_{!} \mathcal{P}_{\circ}
\to 
(\operatorname{id} \times p)^* (i\times \operatorname{id})_{*}\mathcal{P}_{\mathrm{S}/\mathrm{P}}.
\end{align}
We have the isomorphisms (see (\ref{dia:alpha}) for the notation of the morphisms)
\begin{align*}
(\operatorname{id} \times p)^* (\operatorname{id}\times p)_{!}\mathcal{P}_{\circ}
&\cong (p_{12})_{!}\alpha^* \mathcal{P}_{\circ} \\
&\cong (p_{12})_{!}(p_{12}^* \mathcal{P}_{\circ}\otimes p_{13}^* \mathcal{L}) \\
&\cong \mathcal{P}_{\circ}\otimes (p_{12})_{!}p_{13}^* \mathcal{L}.
\end{align*}
By the following Cartesian diagrams
\begin{align*}
\xymatrix{
(\mathcal{H}_{\circ}(w_0)^{\mathrm{ss}}\times_{\mathcal{B}_{\circ}}\mathcal{H}_{\circ})\times \operatorname{Pic}(C)
\ar[r]^-{p_{13}} \ar[d]_-{p_{12}} \ar@{}[rd]|\square
&
\mathcal{H}_{\circ}(w_0)^{\mathrm{ss}}\times \operatorname{Pic}(C)
\ar[r]^-{\mathrm{Nm}\times \operatorname{id}} \ar[d]_-{p_1} \ar@{}[rd]|\square
&
\operatorname{Pic}(C) \times \operatorname{Pic}(C) \ar[d]_-{q}
\\
\mathcal{H}_{\circ}(w_0)^{\mathrm{ss}}\times_{\mathcal{B}_{\circ}}\mathcal{H}_{\circ}
\ar[r]^-{r}
&
\mathcal{H}_{\circ}(w_0)^{\mathrm{ss}}
\ar[r]^-{\mathrm{Nm}}
&
\operatorname{Pic}(C)
}
\end{align*}
where $q$ and $r$ are the first projections, 
we have the isomorphisms
\begin{align*}
(p_{12})_{!}p_{13}^* \mathcal{L}
&\cong r^* (p_1)_{!}\mathcal{L} \\
&\cong r^* (p_1)_{!}(\mathrm{Nm}\times \operatorname{id})^* \mathcal{P}_C \\
&\cong r^* \mathrm{Nm}^* q_{!}\mathcal{P}_C.
\end{align*}
By Lemma~\ref{lem:Pc} below, we have $q_{!}\mathcal{P}_C \cong i_{*}\mathcal{O}_{\mathrm{pt}}$, and 
\begin{align*}
    (p_{12})_{!}p_{13}^* \mathcal{L} \cong r^* \mathrm{Nm}^* i_{*}\mathcal{O}_{\mathrm{pt}} 
    \cong (i\times \operatorname{id})_{*}\mathcal{O}_{\mathcal{H}_{\mathrm{S}}(w_0)^{\mathrm{ss}}\times_{\mathcal{B}_{\circ}}\mathcal{H}_{\circ}}.
\end{align*}
It follows that 
\begin{align*}
    (\operatorname{id} \times p)^* (\operatorname{id} \times p)_{!}\mathcal{P}_{\circ} &\cong \mathcal{P}_{\circ}\otimes 
    (i\times \operatorname{id})_{*}\mathcal{O}_{\mathcal{H}_{\mathrm{S}}(w_0)^{\mathrm{ss}}\times_{\mathcal{B}_{\circ}}\mathcal{H}_{\circ}} 
    \\
    &\cong (i\times \operatorname{id})_{*}(i\times \operatorname{id})^* \mathcal{P}_{\circ}.
\end{align*}

On the other hand, by the Cartesian square (\ref{dia:SP}) and the isomorphism (\ref{isom:PSP}), we have 
\begin{align*}
    (\operatorname{id} \times p)^* (i\times \operatorname{id})_{*}\mathcal{P}_{\mathrm{S}/\mathrm{P}} &\cong (i\times \operatorname{id})_{*}(\operatorname{id} \times p)^* \mathcal{P}_{\mathrm{S}/\mathrm{P}} \\
    &\cong (i\times \operatorname{id})_{*}(i\times \operatorname{id})^* \mathcal{P}_{\circ}.
\end{align*}
Therefore both sides in (\ref{idp*}) are canonically identified with 
$(i\times \operatorname{id})_{*}(i\times \operatorname{id})^*\mathcal{P}_{\circ}$, and the map (\ref{idp*}) 
corresponds to the identity map under the above identifications. 
In particular the map (\ref{idp*}) is an isomorphism. 

Since $\operatorname{id}\times p$ is a smooth surjective morphism, the functor 
\begin{align*}
    (\operatorname{id} \times p)^* \colon \operatorname{Coh}(\mathcal{H}_{\circ}(w_0)^{\mathrm{ss}}\times_{\mathcal{B}_{\circ}}\mathcal{H}_{\mathrm{P}}) \to \operatorname{Coh}(\mathcal{H}_{\circ}(w_0)^{\mathrm{ss}}\times_{\mathcal{B}_{\circ}}\mathcal{H}_{\circ}) 
\end{align*}
is conservative. Therefore, 
we conclude that the map $\gamma$ is an isomorphism.

\label{lem:Pc}
    There is an isomorphism in $\operatorname{QCoh}(\operatorname{Pic}^0(C))$
    \begin{align*}
        q_{!}\mathcal{P}_C \cong i_{*}\mathcal{O}_{\mathrm{pt}}.
    \end{align*}
    Here by abuse of notation $i$ is the composition 
    \begin{align*}
i \colon \mathrm{pt}
\stackrel{\eta}{\to}
B\mathbb{G}_m
\stackrel{0}{\hookrightarrow}
\operatorname{Pic}^0(C),
\end{align*}
and $0$ is the closed immersion corresponds to $\mathcal{O}_C$.

    Note that $q_{!}=q_{*}[g]$.
We have the decomposition into connected components
\begin{align*}
\operatorname{Pic}(C)=\bigsqcup_{a\in \mathbb{Z}}\operatorname{Pic}^a(C),
\end{align*}
where $\operatorname{Pic}^a(C)$ corresponds to degree $a$ line bundles on $C$.
Moreover, $\operatorname{Pic}^a(C)\times \operatorname{Pic}^b(C)$ is a $\mathbb{G}_m^2$-gerbe over the product of the Jacobian of $C$. The line bundle
\begin{align*}
\mathcal{P}_C|_{\operatorname{Pic}^a(C)\times \operatorname{Pic}^b(C)}
\to
\operatorname{Pic}^a(C) \times \operatorname{Pic}^b(C)
\end{align*}
has $\mathbb{G}_m^2$-weight $(b,a)$; therefore
\begin{align*}
q_{*}\left(\mathcal{P}_C|_{\operatorname{Pic}^a(C)\times \operatorname{Pic}^b(C)}\right)=0
\end{align*}
unless $a=0$. For $a=0$, we have
\begin{align*}
(q_{*}\mathcal{P}_C)|_{\operatorname{Pic}^0(C)}
=
\bigoplus_{b\in \mathbb{Z}}
q_{*}\left(\mathcal{P}_C|_{\operatorname{Pic}^0(C)\times \operatorname{Pic}^b(C)}\right).
\end{align*}
The line bundle $\mathcal{P}_C^{\vee}|_{\operatorname{Pic}^0(C)\times \operatorname{Pic}^b(C)}$ induces the Fourier--Mukai equivalence (as a special case of Theorem~\ref{thm:MRV})
\begin{align*}
\Phi_C \colon 
\operatorname{Coh}(\operatorname{Pic}^0(C))_{-b}
\stackrel{\sim}{\to}
\operatorname{Coh}(\operatorname{Pic}^b(C))_0
\end{align*}
such that
\begin{align*}
\Phi_C((\mathcal{O}_0)_{-b})
\cong
\mathcal{O}_{\operatorname{Pic}^b(C)}.
\end{align*}
Here, setting 
$
0 \colon B\mathbb{G}_m \hookrightarrow \operatorname{Pic}^0(C)
$
to be the closed immersion corresponding to $\mathcal{O}_C$, the sheaf $(\mathcal{O}_0)_b$ is defined by
\begin{align*}
(\mathcal{O}_0)_b
=
0_{*}\mathcal{O}_{B\mathbb{G}_m}(b)
\in
\operatorname{Coh}(\operatorname{Pic}^0(C))_b.
\end{align*}
It follows that
\begin{align*}
\Phi_C^{-1}(\mathcal{O}_{\operatorname{Pic}^b(C)})
\cong
(\mathcal{O}_0)_{-b}.
\end{align*}
The kernel object of $\Phi_C^{-1}$ is given by $\mathcal{P}_C[g]$; therefore
\begin{align*}
(q_{!}\mathcal{P}_C)|_{\operatorname{Pic}^0(C)}
\cong
\bigoplus_{b\in \mathbb{Z}}(\mathcal{O}_0)_b
=
i_{*}\mathcal{O}_{\mathrm{pt}}.
\end{align*}
The last isomorphism follows from
\begin{align*}
\eta_{*}\mathcal{O}_{\mathrm{pt}}
=
k[t^{\pm 1}]
=
\bigoplus_{b\in \mathbb{Z}}\mathcal{O}_{B\mathbb{G}_m}(b).
\end{align*}
Therefore we conclude that
$
q_! \mathcal{P}_C \cong i_{*}\mathcal{O}_{\mathrm{pt}}.
$

\label{lem:pL}
An object $A \in \operatorname{Coh}(\mathcal{H}_{\mathrm{P}}(\overline{\chi}))_0$ lies in $\operatorname{L}_{\mathcal{N}}(\mathcal{H}_{\mathrm{P}}(\overline{\chi}))_0$
if and only if $p^* A \in \operatorname{L}_{\mathcal{N}}(\mathcal{H}_{\circ}(\chi))_0$.

For a map $\nu \colon B\mathbb{G}_m \to \mathcal{H}_{\mathrm{P}}(\overline{\chi})$, we consider the fiber 
product 
\begin{align*}
    \xymatrix{
\mathcal{H}_{\circ}(\chi)\times_{\mathcal{H}_{\mathrm{P}}(\overline{\chi})}B\mathbb{G}_m \ar[r]^-{\widetilde{\nu}} \ar[d] \ar@{}[rd]|\square & 
\mathcal{H}_{\circ}(\chi) \ar[d]_-{p} \\
B\mathbb{G}_m \ar[r]^-{\nu} & \mathcal{H}_{\mathrm{P}}(\overline{\chi}).
    }
\end{align*}
Let $x=\nu(\mathrm{pt})$. 
The fiber of $p$ at $x$ is $\operatorname{Pic}^0(C)$, on which $\mathbb{G}_m$ acts 
through $\nu$. The above $\mathbb{G}_m$-action is trivial since 
an abelian variety does not contain a rational curve; therefore 
\begin{align}\label{dia:nupull}
    \mathcal{H}_{\circ}(\chi)\times_{\mathcal{H}_{\mathrm{P}}(\overline{\chi})}B\mathbb{G}_m\cong \operatorname{Pic}^0(C)\times B\mathbb{G}_m
\end{align}
and the left vertical arrow in (\ref{dia:nupull}) is identified with the projection. 
Therefore for $A \in \operatorname{Coh}_{\mathcal{N}}(\mathcal{H}_{\circ}(\chi))$, if 
we have 
\begin{align*}
    \widetilde{\nu}^* A \in \bigoplus_{w\in I}\operatorname{Coh}(\operatorname{Pic}^0(C)\times B\mathbb{G}_m)_{w}
\end{align*}
for an interval $I\subset \mathbb{R}$, then by base change we have 
$\mathrm{wt}(\nu^*p_{!}A) \subset I$. 
It follows if $A \in \operatorname{L}_{\mathcal{N}}(\mathcal{H}_{\circ}(\chi))_0$, then 
$p_{!}A \in \widetilde{\operatorname{L}}_{\mathcal{N}}(\mathcal{H}_{\mathrm{P}}(\overline{\chi}))_0$. 
Since the map $p$ is compatible with Harder--Narasimhan stratification as in the proof of Lemma~\ref{lem:pL}, the lemma holds.

Let
\begin{align*}
\Phi_{\mathrm{S}/\mathrm{P}}^R \colon
\operatorname{IndL}_{\mathcal{N}}(\mathcal{H}_{\mathrm{P}}(\overline{\chi}))_0
\to
\operatorname{IndCoh}_{\mathcal{N}}(\mathcal{H}_{\mathrm{S}}(w_0)^{\mathrm{ss}})_{-\overline{\chi}}
\end{align*}
be the right adjoint of the functor $\Phi_{\mathrm{S}/\mathrm{P}}$ in (\ref{funct:SP}), which exists and is continuous by the adjoint functor theorem. By taking right adjoints in \eqref{dia:pL2}, we have the commutative diagram
\begin{align}\label{dia:pR}
\xymatrix{
\operatorname{IndCoh}_{\mathcal{N}}(\mathcal{H}_{\mathrm{S}}(w_0)^{\mathrm{ss}})_{-\overline{\chi}} \ar[d]_-{i_{*}}
&
\operatorname{IndL}_{\mathcal{N}}(\mathcal{H}_{\mathrm{P}}(\overline{\chi}))_0
\ar[l]_-{\Phi_{\mathrm{S}/\mathrm{P}}^R} \ar[d]_-{p^*}
\\
\operatorname{IndCoh}_{\mathcal{N}}(\mathcal{H}_{\circ}(w_0)^{\mathrm{ss}})_{-\chi'}
&
\operatorname{IndL}_{\mathcal{N}}(\mathcal{H}_{\circ}(\chi))_0
\ar[l]_-{\Phi^R}.
}
\end{align}
Consider the following natural transform 
\begin{align}\label{nat:R}
    \operatorname{id} \Rightarrow \Phi_{\mathrm{S}/\mathrm{P}}^R \circ \Phi_{\mathrm{S}/\mathrm{P}}.
\end{align}
By applying $i_{*}$, we obtain 
\begin{align}\label{apply:i}
i_{*} \Rightarrow i_{*}\circ\Phi_{\mathrm{S}/\mathrm{P}}^R \circ \Phi_{\mathrm{S}/\mathrm{P}}.
\end{align}
By the commutative diagrams (\ref{commute:PhiL2}) and (\ref{dia:pR}), 
we have 
\begin{align*}
    i_{*}\circ \Phi_{\mathrm{S}/\mathrm{P}}^R \circ \Phi_{\mathrm{S}/\mathrm{P}} &\cong \Phi^R \circ p^* \circ \Phi_{\mathrm{S}/\mathrm{P}} \\
    &\cong \Phi^R \circ \Phi \circ i_{*} \\
    &\cong i_{*}
\end{align*}
where the last isomorphism follows from the fact that $\Phi$ is an equivalence (\ref{equiv:HGL}). 
Under the above isomorphisms, the natural transform (\ref{apply:i}) is 
$\operatorname{id} \colon i_{*} \Rightarrow i_{*}$, therefore 
(\ref{apply:i}) is an isomorphism. Then (\ref{nat:R}) is an isomorphism 
since $i_{*}$ is conservative; the conservativity of $i_{*}$ follows 
from the factorization (\ref{compose:0i}) and the map $0$ in (\ref{factor:i}) 
is a closed immersion. 

Similarly we have the natural transform 
\begin{align}\label{nat:L}
    \Phi_{\mathrm{S}/\mathrm{P}} \circ \Phi_{\mathrm{S}/\mathrm{P}}^R \Rightarrow \operatorname{id}.
\end{align}
By applying $p^*$ and using the commutative diagrams (\ref{commute:PhiL2}), (\ref{dia:pR}), 
we obtain 
\begin{align*}
  p^*\cong  p^*  \circ \Phi_{\mathrm{S}/\mathrm{P}} \circ \Phi_{\mathrm{S}/\mathrm{P}}^R \Rightarrow p^*.
\end{align*}
Since $p$ is a smooth morphism with fiber $\operatorname{Pic}^0(C)$, the functor $p^*$ is 
conservative. Therefore (\ref{nat:L}) is an isomorphism, and 
the functor (\ref{funct:SP}) is an equivalence.

\label{thm:SL}
The DL conjecture holds for $(^{L}G, G)=(\operatorname{SL}_r, \operatorname{PGL}_r)$ 
over $\mathrm{B}_{G}^A:=\mathrm{B}_{\operatorname{GL}_r}^A \cap \mathrm{B}_{G}$.

Recall from (\ref{factor:i}) that $i$ factors as 
\begin{align}\label{factor:i2}
   \mathcal{H}_{\mathrm{S}}(\chi_0) \stackrel{\widetilde{i}}{\to} \widetilde{\mathcal{H}}_{\circ}(\chi_0) \stackrel{0}{\to} \mathcal{H}_{\circ}(\chi_0), 
\end{align}
and from 
(\ref{compose:0i}) that $i_{*}$ factors as 
\begin{align}\label{factor:i*}
\operatorname{Coh}(\mathcal{H}_{\mathrm{S}}(\chi_0))_{\overline{w}} 
\stackrel{\sim}{\to} 
\operatorname{Coh}(\widetilde{\mathcal{H}}_{\circ}(\chi_0))_{w'} 
\stackrel{0_{*}}{\to}
\operatorname{Coh}(\mathcal{H}_{\circ}(\chi_0))_{w'}.
\end{align}
The above functors preserve perfect complexes, as 
the first map $\widetilde{i}$ in~\eqref{factor:i2} is smooth, and the second 
map $0$ in~\eqref{factor:i2} is a quasi-smooth closed immersion. 
By Remark~\ref{rmk:perfSP}, they preserve nilpotent singular supports. 

We first show that the first equivalence restricts to an equivalence
\begin{align}\label{equiv:rest}
\operatorname{L}_{\mathcal{N}}(\mathcal{H}_{\mathrm{S}}(\chi_0))_{\overline{w}} 
\stackrel{\sim}{\to} 
\operatorname{L}_{\mathcal{N}}(\widetilde{\mathcal{H}}_{\circ}(\chi_0))_{w'}.
\end{align}
Let $\nu \colon B\mathbb{G}_m \to \mathcal{H}_{\mathrm{S}}(\chi_0)$ be a test map, and consider the composition 
\begin{align*}
\widetilde{\nu} \colon 
B\mathbb{G}_m \stackrel{\nu}{\to} \mathcal{H}_{\mathrm{S}}(\chi_0) 
\stackrel{\widetilde{i}}{\to} 
\widetilde{\mathcal{H}}_{\circ}(\chi_0).
\end{align*}
Then we have 
\begin{align*}
c_1\bigl(
\widetilde{\nu}^* 
\mathbb{L}^{>0}_{\widetilde{\mathcal{H}}_{\circ}(\chi_0)}
\bigr)
=
c_1\bigl(
\nu^* 
\mathbb{L}_{\mathcal{H}_{\mathrm{S}}(\chi_0)}^{>0}
\bigr), \ c_1\bigl(
\widetilde{\nu}^* 
\mathbb{L}^{<0}_{\widetilde{\mathcal{H}}_{\circ}(\chi_0)}
\bigr)
=
c_1\bigl(
\nu^* 
\mathbb{L}_{\mathcal{H}_{\mathrm{S}}(\chi_0)}^{<0}
\bigr).
\end{align*}
Indeed, we have a distinguished triangle
\begin{align*}
\widetilde{i}^* \mathbb{L}_{\widetilde{\mathcal{H}}_{\circ}(\chi_0)}
\to 
\mathbb{L}_{\mathcal{H}_{\mathrm{S}}(\chi_0)}
\to 
\mathbb{L}_{\widetilde{i}}.
\end{align*}
Moreover, $\mathbb{L}_{\widetilde{i}}$ has no non-trivial $\nu$-weights.

Conversely, let 
$\widetilde{\nu} \colon B\mathbb{G}_m \to \widetilde{\mathcal{H}}_{\circ}(\chi_0)$ 
be a test map whose image is a point $x$. Let $m\in \mathbb{Z}$ be the weight 
of the composition
\begin{align*}
\mathbb{G}_m \to \operatorname{Aut}(x) 
\stackrel{\mathrm{Nm}}{\to} 
\mathbb{G}_m
\end{align*}
where the first map is induced by $\widetilde{\nu}$. 
We modify $\widetilde{\nu}$ by setting 
\begin{align*}
  \widetilde{\nu}' \colon B\mathbb{G}_m \to \widetilde{\mathcal{H}}_{\circ}(\chi_0), \ 
  \mathrm{pt} \mapsto x, \ \mathbb{G}_m \stackrel{\widetilde{\nu}(t^r)\cdot t^{-m}}{\to}\mathrm{Aut}(x).
\end{align*}
Then $\widetilde\nu(t^r)$ has norm weight $rm$, while the scalar automorphism
$t^{-m}$ has norm weight $-rm$. Hence
$\widetilde\nu'$ has trivial norm weight and factors through
$\mathcal{H}_{\mathrm{S}}(\chi_0)$:
\begin{align*}
\widetilde{\nu}' \colon 
  B\mathbb{G}_m \stackrel{\nu'}{\to} \mathcal{H}_{\mathrm{S}}(\chi_0) 
  \stackrel{\widetilde{i}}{\to} 
  \widetilde{\mathcal{H}}_{\circ}(\chi_0).
\end{align*}
Since 
$\mathbb{G}_m \subset \operatorname{Aut}(x)$ acts trivially on the cotangent complex at $x$, 
we have 
\begin{align*}
c_1\bigl(
(\widetilde{\nu}')^* 
\mathbb{L}^{>0}_{\widetilde{\mathcal{H}}_{\circ}(\chi_0)}
\bigr) 
=
c_1\bigl(
(\nu')^* 
\mathbb{L}_{\mathcal{H}_{\mathrm{S}}(\chi_0)}^{>0}
\bigr)=r\cdot c_1\bigl(
\widetilde{\nu}^{*}
\mathbb{L}^{>0}_{\widetilde{\mathcal{H}}_{\circ}(\chi_0)}
\bigr),
\end{align*}
and similarly for the negative weight part. 
Therefore, the test maps from $B\mathbb{G}_m$ and their associated $c_1$-values are 
identified under the first equivalence in (\ref{factor:i*}), up to the modification of the test 
map by composing with $\mathbb{G}_m \to \mathbb{G}_m, t\mapsto t^r$, and multiplying $c_1$ with $r$. 
The latter modification does not affect the condition (\ref{wt:cond2}), see Remark~\ref{rmk:cond:r}. 
Hence this equivalence restricts 
to the equivalence~\eqref{equiv:rest}.

We next show that an object 
$A\in \operatorname{Coh}_{\mathcal{N}}(\widetilde{\mathcal{H}}_{\circ}(\chi_0))_{w'}$ lies in 
$\operatorname{L}_{\mathcal{N}}(\widetilde{\mathcal{H}}_{\circ}(\chi_0))_{w'}$ if and only if 
$0_{*}A$ lies in $\operatorname{L}_{\mathcal{N}}(\mathcal{H}_{\circ}(\chi_0))_{w'}$. 
Indeed, this follows from the fact that $0^*0_{*}A$
is given by iterated extensions of 
\begin{align*}
    A \otimes \bigwedge^i H^1(\mathcal{O}_C)^{\vee}[i],
    \quad 0\leqslant i\leqslant g.
\end{align*}
Therefore, for any map 
$\nu \colon B\mathbb{G}_m \to \widetilde{\mathcal{H}}_{\circ}(\chi_0)$, 
the relevant weight condition for $A$ with respect to $\nu$ agrees with 
the weight condition for $0_{*}A$ with respect to 
$0\circ \nu \colon B\mathbb{G}_m \to \mathcal{H}_{\circ}(\chi_0)$.

\label{lem:i!2}
For an object $A\in \operatorname{L}_{\mathcal{N}}(\mathcal{H}_{\circ}(\chi_0))_{w'}$, 
we have $i^* A \in \operatorname{L}_{\mathcal{N}}(\mathcal{H}_{\mathrm{S}}(\chi_0))_{\overline{w}}$.

\label{prop:restL}
The functor (\ref{Phi:PS})
   restricts to the functor 
   \begin{align}\label{funct:PhiPSL}
   \Phi_{\mathrm{P}/\mathrm{S}} \colon
\operatorname{Coh}_{\mathcal{N}}(\mathcal{H}_{\mathrm{P}}(\overline{w})^{\mathrm{ss}})_0
\to
\operatorname{L}_{\mathcal{N}}(\mathcal{H}_{\mathrm{S}}(\chi_0))_{\overline{w}}
\end{align}
such that 
we have commutative diagrams 
\begin{align}\label{comm:PSL}
\xymatrix{
\operatorname{Coh}_{\mathcal{N}}(\mathcal{H}_{\mathrm{P}}(\overline{w})^{\mathrm{ss}})_0
\ar[r]^-{\Phi_{\mathrm{P}/\mathrm{S}}}
&
\operatorname{L}_{\mathcal{N}}(\mathcal{H}_{\mathrm{S}}(\chi_0))_{\overline{w}}
\\
\operatorname{Coh}_{\mathcal{N}}(\mathcal{H}_{\circ}(w)^{\mathrm{ss}})_0
\ar[r]^-{\Phi}_-{\sim}
\ar[u]^-{p_*}
&
\operatorname{L}_{\mathcal{N}}(\mathcal{H}_{\circ}(\chi_0))_{w'}
\ar[u]_-{i^*},
}
\end{align}
\begin{align}\label{comm:PS2L}
\xymatrix{
\operatorname{Coh}_{\mathcal{N}}(\mathcal{H}_{\mathrm{P}}(\overline{w})^{\mathrm{ss}})_0
\ar[r]^-{\Phi_{\mathrm{P}/\mathrm{S}}} \ar[d]_-{p^!}
&
\operatorname{L}_{\mathcal{N}}(\mathcal{H}_{\mathrm{S}}(\chi_0))_{\overline{w}} \ar[d]_-{i_{*}}
\\
\operatorname{Coh}_{\mathcal{N}}(\mathcal{H}_{\circ}(w)^{\mathrm{ss}})_0
\ar[r]^-{\Phi}_-{\sim}
&
\operatorname{L}_{\mathcal{N}}(\mathcal{H}_{\circ}(\chi_0))_{w'}.
}
\end{align}

Since the functor $\Phi$ gives an equivalence by Theorem~\ref{thm:GL}
\begin{align*}
