\label{lem:equiv:k}
There is an equivalence
\begin{align}\label{equiv:k-1}
    \operatorname{IndL}_{\mathcal{N}}(\mathfrak{M}_{\circ})_{\delta}
    \otimes \operatorname{QCoh}(k[-1])
    \stackrel{\sim}{\to}
    \operatorname{IndL}_{\mathcal{N}}(\mathfrak{M})_{\delta}.
\end{align}
In particular, we have the equivalence 
\begin{align*}
      \operatorname{IndL}_{\mathcal{N}}(\mathfrak{M}_{\circ})_{\delta}
    \stackrel{\sim}{\to}
    \operatorname{IndL}_{\mathcal{N}}(\mathfrak{M})_{\delta}\otimes_{\operatorname{QCoh}(k[-1])}\operatorname{QCoh}(\mathrm{pt}).
\end{align*}

By~\cite[Corollary~4.2.3]{MR3037900}, we have an equivalence
\begin{align}\label{equiv:k0}
    \operatorname{IndCoh}(\mathfrak{M}_{\circ}) \otimes \operatorname{QCoh}(k[-1])
    \stackrel{\sim}{\to}
    \operatorname{IndCoh}(\mathfrak{M}).
\end{align}
This equivalence restricts to an equivalence
\begin{align}\label{equiv:k2}
    \operatorname{IndCoh}_{\mathcal{N}}(\mathfrak{M}_{\circ}) \otimes \operatorname{QCoh}(k[-1])
    \stackrel{\sim}{\to}
    \operatorname{IndCoh}_{\mathcal{N}}(\mathfrak{M}).
\end{align}
Indeed, this follows from the scheme case in~\cite[Lemma~4.6.4]{AG}, together
with descent for singular supports in~\cite[Section~8.3]{AG}.
We show that the equivalence \eqref{equiv:k2} restricts to an equivalence
\eqref{equiv:k-1}.

We first prove this when $\mathfrak{M}$ is QCA. By Lemma~\ref{lem:eta},
the equivalence restricts to a fully faithful functor
\begin{align}\label{equiv:kl}
    \operatorname{IndL}_{\mathcal{N}}(\mathfrak{M}_{\circ})_{\delta}
    \otimes \operatorname{QCoh}(k[-1])
    \hookrightarrow
    \operatorname{IndL}_{\mathcal{N}}(\mathfrak{M})_{\delta}.
\end{align}
On the other hand, for an object $M \in \operatorname{QCoh}(k[-1])$, there is a functorial
bar resolution for $R=\mathcal{O}_{k[-1]}$:
\begin{align*}
    \cdots \to M \otimes R^{\otimes n} \to \cdots
    \to M \otimes R \to M.
\end{align*}
Applying this resolution to the left-hand side of \eqref{equiv:k0}, and then
using the equivalence \eqref{equiv:k0}, we see that any object
$A \in \operatorname{IndCoh}_{\mathcal{N}}(\mathfrak{M})$ is expressed as a colimit
\begin{align*}
\operatorname*{colim}_{n\to \infty}
    \left(
    0 \to \eta^* \eta_* A \otimes R^{\otimes n}
    \to \cdots
    \to \eta^* \eta_* A \otimes R
    \to \eta^* \eta_* A
    \right)
    \stackrel{\sim}{\to} A.
\end{align*}
Here $\eta^*$ is defined for ind-coherent sheaves since $\eta$ is
quasi-smooth; see Subsection~\ref{subsec:notation0}.
By Lemma~\ref{lem:eta2}, if
$A \in \operatorname{IndL}_{\mathcal{N}}(\mathfrak{M})_{\delta}$, then
$\eta_* A \in \operatorname{IndL}_{\mathcal{N}}(\mathfrak{M}_{\circ})_{\delta}$.
Therefore \eqref{equiv:kl} is essentially surjective, and hence an equivalence.

In general, when $\mathfrak{M}$ is not QCA, the equivalence \eqref{equiv:k-1}
follows from the QCA case, since tensoring with $\operatorname{QCoh}(k[-1])$ commutes with
limits, as $\operatorname{QCoh}(k[-1])$ is dualizable; see~\cite[4.1.3(iii)]{MR3037900}.

\begin{align*}
    \cdots \to M \otimes R^{\otimes n} \to \cdots
    \to M \otimes R \to M.
\end{align*}

\begin{align*}
\operatorname*{colim}_{n\to \infty}
    \left(
    0 \to \eta^* \eta_* A \otimes R^{\otimes n}
    \to \cdots
    \to \eta^* \eta_* A \otimes R
    \to \eta^* \eta_* A
    \right)
    \stackrel{\sim}{\to} A.
\end{align*}

Then by~\cite[Corollary~4.2.3]{MR3037900} and \cite[Lemma~4.6.4, Section~8.3]{AG}, 
we have the equivalence 
\begin{align}\label{equiv:Y1}
    \operatorname{IndCoh}_{\mathcal{N}}(\mathfrak{M}_0)\otimes \operatorname{QCoh}(Y) \stackrel{\sim}{\to} \operatorname{IndCoh}_{\mathcal{N}}(\mathfrak{M}_{\circ}'). 
\end{align}

\label{lem:resty}
The equivalence \eqref{equiv:Y2} restricts to an equivalence
\begin{align}\label{equiv:Y3}
\operatorname{IndL}_{\mathcal{N}}(\mathfrak{M}_{\circ})_{\delta}
\stackrel{\sim}{\to}
\operatorname{IndL}_{\mathcal{N}}(\mathfrak{M}_{\circ}')_{\delta}
\otimes_{\operatorname{QCoh}(Y)}
\operatorname{QCoh}(\mathrm{pt}).
\end{align}

It is clear that the pullback along the smooth projection
$\mathfrak{M}_{\circ}'\to \mathfrak{M}_{\circ}$
induces the functor 
\begin{align*}
    \operatorname{IndL}_{\mathcal{N}}(\mathfrak{M}_{\circ})_{\delta} \to 
    \operatorname{IndL}_{\mathcal{N}}(\mathfrak{M}_{\circ}')_{\delta}.
\end{align*}
Therefore, the functor in \eqref{equiv:Y2}
restricts to a fully faithful functor
\begin{align}\label{equiv:LNQ}
\operatorname{IndL}_{\mathcal{N}}(\mathfrak{M}_{\circ})_{\delta}
\hookrightarrow
\operatorname{IndL}_{\mathcal{N}}(\mathfrak{M}_{\circ}')_{\delta}
\otimes_{\operatorname{QCoh}(Y)}
\operatorname{QCoh}(\mathrm{pt}).
\end{align}

On the other hand, the right-hand side of \eqref{equiv:Y2} is computed
as the colimit of the bar construction:
\begin{align}\label{bar:Y:colim}
\operatorname*{colim}_{[n]\in \Delta^{\mathrm{op}}}
\left(
\operatorname{IndCoh}_{\mathcal{N}}(\mathfrak{M}_{\circ}')
\otimes
\operatorname{QCoh}(Y)^{\otimes n}
\otimes
\operatorname{QCoh}(\mathrm{pt})
\right).
\end{align}

An inverse functor to \eqref{equiv:Y2} is induced termwise on the bar
construction by the functors
\begin{align*}
\operatorname{IndCoh}_{\mathcal{N}}(\mathfrak{M}_{\circ}')
\otimes
\operatorname{QCoh}(Y)^{\otimes n}
\otimes
\operatorname{QCoh}(\mathrm{pt})
\longrightarrow
\operatorname{IndCoh}_{\mathcal{N}}(\mathfrak{M}_{\circ}),
\end{align*}
obtained by restricting to the fiber
$\mathfrak{M}_{\circ}'\times_Y \{y\}$ and applying $(i_y^*)^{\otimes n}$
to the $\operatorname{QCoh}(Y)$-factors, where $i_y\colon \mathrm{pt}\to Y$ is the
corresponding point. By the definition of limit categories, these functors
restrict to
\begin{align*}
\operatorname{IndL}_{\mathcal{N}}(\mathfrak{M}_{\circ}')_{\delta}
\otimes
\operatorname{QCoh}(Y)^{\otimes n}
\otimes
\operatorname{QCoh}(\mathrm{pt})
\longrightarrow
\operatorname{IndL}_{\mathcal{N}}(\mathfrak{M}_{\circ})_{\delta}.
\end{align*}
Taking the colimit, we obtain an inverse to
\eqref{equiv:LNQ}. Hence \eqref{equiv:LNQ} is an equivalence.

